const app = document.querySelector('#app');
const API = '/api';
const DEFAULT_STATE = {screen:'landing', category:'', district:'Kathmandu', report:'', emergencyRequested:false, messages:[], files:[], pendingFiles:[], matches:[], referrals:[], selectedNgoId:'', ngoToken:'', adminToken:'', caseId:'', status:'open', caseStatus:'pending', analysisStatus:'pending', backend:false, aiLegalSummary:'', severity:'', analysisQuestions:[], timeline:[], clarifyingQa:[], sessionToken:'', isAuthenticated:false, sosId:'', sosToken:''};
const state = {...DEFAULT_STATE};
const uploadControllers = new Set();
let uploadInFlight = false;
let retryInFlight = false;
const EXIT_REDIRECT_URL = 'https://www.google.com/';
const categories = [['harassment','campaign','Harassment','Unwanted messages, comments, or attention'],['domestic_violence','home','Domestic violence','Harm or control from someone at home'],['stalking','visibility_off','Stalking','Repeated unwanted following or contact'],['workplace','work','Workplace abuse','Abuse, threats, or harassment at work'],['other','help_outline','Something else','Anything that does not fit above']];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function authenticate(caseId, ip = null, userAgent = null) {
  const response = await fetch(`${API}/auth/login`, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({ identifier: caseId, ip_address: ip, user_agent: userAgent })
  });
  if (!response.ok) throw new Error((await response.json().catch(() => ({}))).detail || `Auth failed (${response.status})`);
  const data = await response.json();
  state.sessionToken = data.session_token;
  state.isAuthenticated = true;
  return data;
}
async function logoutSession() {
  if (!state.sessionToken) return;
  try {
    const response = await fetch(`${API}/auth/logout`, {
      method: 'POST',
      headers: {'Authorization': `Bearer ${state.sessionToken}`}
    });
    if (!response.ok) {
      const error = await response.json().catch(() => ({}));
      throw new Error(error.detail || `Logout failed (${response.status})`);
    }
    await response.json();
  } catch (error) {
    console.error('Logout failed, but continuing:', error);
  }
  state.sessionToken = '';
  state.isAuthenticated = false;
}
async function api(path, options={}) {
  options={...options,headers:{...(options.headers||{})}};
  if(state.sessionToken) options.headers.Authorization=`Bearer ${state.sessionToken}`;
  const response=await fetch(`${API}${path}`,options);
  if(!response.ok) {
    const error = await response.json().catch(() => ({}));
    if (response.status === 401 && error.detail === 'Invalid or inactive session') {
      await logoutSession();
    }
    const fallback = response.status === 413
      ? 'Evidence file exceeds the 50MB upload limit.'
      : response.status === 415
        ? 'This evidence file type or content is not supported.'
        : `API request failed (${response.status})`;
    throw new Error(error.detail || fallback);
  }
  return response.json();
}
function clearSessionState(){
  for(const controller of uploadControllers){try{controller.abort()}catch(_error){}}
  uploadControllers.clear();
  Object.assign(state, {screen:'landing', category:'', district:'Kathmandu', report:'', emergencyRequested:false, messages:[], files:[], pendingFiles:[], matches:[], caseId:'', status:'open', caseStatus:'pending', analysisStatus:'pending', backend:false, aiLegalSummary:'', severity:'', analysisQuestions:[], timeline:[], clarifyingQa:[], sessionToken:'', isAuthenticated:false, sosId:'', sosToken:''});
  try{sessionStorage.clear()}catch(_error){}
}
async function handleQuickExit(redirect=EXIT_REDIRECT_URL){
  try{await logoutSession()}catch(_error){/* logout failure must never block exit */}
  clearSessionState();
  try{window.location.replace(redirect)}catch(_error){try{location.replace(redirect)}catch(_ignored){}}
}
function icon(name){return `<span class="material-symbols-outlined">${name}</span>`}
function isNgoRoute(pathname=typeof window!=='undefined'?window.location.pathname:''){return /^\/(?:ngo|admin)(?:\/|$)/i.test(pathname)}
function header(dashboard=false){const showQuickExit=!isNgoRoute();return `<header class="app-header"><a class="brand" href="#" data-action="home">${icon('security')}<span>VaultVoice</span></a>${dashboard?`<nav class="dashboard-nav"><a class="active" href="#" data-action="dashboard">Home</a><a href="#" data-action="evidence">Vault</a><a href="#" data-action="matches">Connect</a></nav>`:''}<button class="btn soft" data-action="donate">${icon('volunteer_activism')} Donate</button>${showQuickExit?`<button class="sos-button" data-action="sos">${icon('sos')} SOS</button><button class="exit" data-action="exit">${icon('logout')}<span>Quick Exit</span></button>`:''}</header>`}
let sosLocationCapture=null;
function sosDialog(){return `<div class="sos-overlay" role="dialog" aria-modal="true" aria-labelledby="sos-title"><section class="sos-dialog"><button class="sos-close" data-action="close-sos" aria-label="Close">${icon('close')}</button><span class="sos-icon">${icon('sos')}</span><h1 id="sos-title">Get immediate help</h1><p>Your SOS goes to the VaultVoice response team. If it is unsafe to wait, call emergency services now.</p><div class="sos-calls"><a class="btn primary" href="tel:100">${icon('call')} Call Nepal Police · 100</a><a class="btn soft" href="tel:1145">${icon('call')} Call 1145</a></div><form data-form="sos"><label class="field-label" for="sos-note">What do responders need to know? <small>(optional)</small></label><textarea id="sos-note" class="textarea" maxlength="2000" placeholder="For example: I am being followed near... "></textarea><label class="emergency-option"><input id="sos-location" type="checkbox" checked> <strong>Share my current location</strong><small>Location is optional. Tap the button below to let your browser ask for permission.</small></label><button class="btn soft full" type="button" data-action="request-sos-location">${icon('my_location')} Use my current location</button><p class="field-note" id="sos-location-status" aria-live="polite">Location has not been requested yet.</p><button class="btn danger full" type="submit">${icon('warning')} Send SOS now</button></form><p class="field-note">Police contact is never automatic. A trained responder reviews escalation with your safety in mind.</p></section></div>`}
function legacyOpenSos(){sosLocationCapture=null;document.body.insertAdjacentHTML('beforeend',sosDialog())}
function closeSos(){document.querySelector('.sos-overlay')?.remove()}
function currentLocation(){if(sosLocationCapture)return Promise.resolve(sosLocationCapture);return new Promise(resolve=>{if(!navigator.geolocation)return resolve(null);navigator.geolocation.getCurrentPosition(position=>resolve({latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy_meters:position.coords.accuracy,location_captured_at:new Date(position.timestamp).toISOString()}),()=>resolve(null),{enableHighAccuracy:true,timeout:10000,maximumAge:30000})})}
async function legacyRequestSosLocation(){const status=document.querySelector('#sos-location-status');if(!document.querySelector('#sos-location')?.checked){if(status)status.textContent='Turn on location sharing first.';return}if(status)status.textContent='Requesting your location permission…';sosLocationCapture=await currentLocation();if(status)status.textContent=sosLocationCapture?`Location ready: ${sosLocationCapture.latitude.toFixed(5)}, ${sosLocationCapture.longitude.toFixed(5)} (accuracy ±${Math.round(sosLocationCapture.accuracy_meters||0)}m). It will be sent with your SOS.`:'Location could not be obtained. Check browser permission and use HTTPS; your SOS can still be sent.'}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="request-sos-location"]'))requestSosLocation()});
let sosLocationAttempt=null;
let sosLocationResult={status:'not_requested',source:'unknown',position:null};
const SOS_LOCATION_TIMEOUT_MS=20000;
function setSosLocationStatus(message){const target=document.querySelector('#sos-location-status');if(target)target.textContent=message}
async function captureSosLocation(){
  console.info('[SOS] Permission requested');
  if(!navigator.geolocation){console.warn('[SOS] Geolocation unsupported');return {status:'unsupported',source:'unknown',position:null}}
  if(!window.isSecureContext&&!['localhost','127.0.0.1','::1'].includes(location.hostname)){console.warn('[SOS] Geolocation blocked: secure context required');return {status:'insecure_context',source:'unknown',position:null}}
  try{
    if(navigator.permissions?.query){
      const permission=await navigator.permissions.query({name:'geolocation'});
      console.info('[SOS] Permission state',permission.state);
      if(permission.state==='denied')return {status:'permission_denied',source:'unknown',position:null};
    }
  }catch(error){console.info('[SOS] Permissions API unavailable; requesting position directly',error)}
  return new Promise(resolve=>{
    let settled=false;
    const finish=result=>{if(settled)return;settled=true;clearTimeout(timer);resolve(result)};
    const timer=setTimeout(()=>{console.warn('[SOS] Location timeout');finish({status:'timeout',source:'unknown',position:null})},SOS_LOCATION_TIMEOUT_MS);
    navigator.geolocation.getCurrentPosition(
      position=>{const value={latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy:position.coords.accuracy,captured_at:new Date(position.timestamp).toISOString()};console.info('[SOS] Coordinates received',value);finish({status:'captured',source:'unknown',position:value})},
      error=>{const status=error.code===error.PERMISSION_DENIED?'permission_denied':error.code===error.TIMEOUT?'timeout':'unavailable';console.warn('[SOS] Location capture failed',status,error.message);finish({status,source:'unknown',position:null})},
      {enableHighAccuracy:true,timeout:SOS_LOCATION_TIMEOUT_MS,maximumAge:0},
    );
  });
}
function requestSosLocation(){if(sosLocationAttempt&&sosLocationResult.status==='captured')return sosLocationAttempt;setSosLocationStatus('Requesting location permission…');sosLocationAttempt=captureSosLocation().then(result=>{sosLocationResult=result;if(result.position){const p=result.position;setSosLocationStatus(`Location ready: ${p.latitude.toFixed(5)}, ${p.longitude.toFixed(5)} (accuracy ±${Math.round(p.accuracy)}m).`)}else setSosLocationStatus(`Location unavailable: ${result.status.replaceAll('_',' ')}. SOS will still send.`);return result});return sosLocationAttempt}
function openSos(){sosLocationAttempt=null;sosLocationResult={status:'not_requested',source:'unknown',position:null};document.body.insertAdjacentHTML('beforeend',sosDialog());requestSosLocation()}
document.addEventListener('submit',async e=>{if(e.target.dataset.form!=='sos')return;e.preventDefault();e.stopImmediatePropagation();const form=e.target;const button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Preparing SOS…';try{const result=await (sosLocationAttempt||requestSosLocation());const payload={case_id:state.caseId||null,note:document.querySelector('#sos-note')?.value.trim()||null,location_status:result.status,location_source:result.source,...(result.position||{})};console.info('[SOS] Coordinates attached to payload',Boolean(result.position),payload);button.textContent='Sending SOS…';const data=await api('/sos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});console.info('[SOS] Backend response',data);state.sosId=data.id;state.sosToken=data.access_token;try{sessionStorage.setItem('vaultvoice-sos',JSON.stringify({id:data.id,token:data.access_token}))}catch(_error){}closeSos();toast(data.latitude!=null?'SOS sent with your location. A responder has been alerted.':`SOS sent without location (${data.location_status.replaceAll('_',' ')}).`)}catch(error){console.error('[SOS] Submission failed',error);button.disabled=false;button.innerHTML=`${icon('warning')} Send SOS now`;toast(error.message)}} ,true);
function progress(active){const labels=['Start','Describe','Understand','Evidence','Connect'];return `<div class="progress">${labels.map((x,i)=>`<div class="step ${i<active?'done':''} ${i===active?'active':''}"><i>${i<active?icon('check'):i+1}</i><span>${x}</span></div>${i<labels.length-1?'<div class="connector"></div>':''}`).join('')}</div>`}
function landing(){return `${header()}<main class="page hero center"><div class="eyebrow">A private place to begin</div><h1 class="display">Your story, in your own time.</h1><p class="subhead">Understand what happened, organize what you remember, and explore your options without creating an account or sharing your identity.</p><div class="hero-actions"><button class="action-tile primary" data-action="category">${icon('edit_document')}<strong>Report something</strong><span>Start a private, anonymous report <b>→</b></span></button><button class="action-tile secondary" data-action="retrieve">${icon('lock_open')}<strong>Check existing case</strong><span>Enter your Case ID to return <b>→</b></span></button></div><div class="trust-row"><div class="trust">${icon('visibility_off')}<div><strong>No account needed</strong><small>Nothing tied to your name</small></div></div><div class="trust">${icon('encrypted')}<div><strong>Private by design</strong><small>Your case stays in your vault</small></div></div><div class="trust">${icon('translate')}<div><strong>English or Nepali</strong><small>Type in the way you feel comfortable</small></div></div></div></main>`}
function retrieve(){return `${header()}<main class="page narrow"><button class="btn soft" data-action="home">${icon('arrow_back')} Back</button><section class="clay panel" style="margin-top:24px"><div class="center">${icon('lock_open')}<h1 class="headline">Enter your Case ID</h1><p class="subhead">This is the only way to access your saved records.</p></div><label class="field-label">Case ID</label><input id="retrieve-id" class="input" placeholder="e.g. VV-8X92LK"/><p class="field-note">Case IDs are not connected to your identity.</p><button class="btn primary full" data-action="open-case">Open my case ${icon('arrow_forward')}</button></section></main>`}
function category(){return `${header()}<main class="page narrow">${progress(0)}<section class="form-shell"><div class="eyebrow">Step 1 of 5</div><h1 class="headline">What would you like help with?</h1><p class="subhead">Choose the category that feels closest. You can explain more in the next step.</p><div class="choice-grid" style="margin-top:24px">${categories.map(([id,ic,title,desc])=>`<button class="choice ${state.category===id?'selected':''}" data-category="${id}">${icon(ic)}<strong>${title}</strong><br><small>${desc}</small></button>`).join('')}</div><div class="form-actions"><button class="btn primary" data-action="report">Continue ${icon('arrow_forward')}</button></div></section></main>`}
function report(){return `${header()}<main class="page narrow">${progress(1)}<section class="form-shell"><div class="eyebrow">Step 2 of 5</div><h1 class="headline">Describe what happened</h1><p class="subhead">Share only what feels safe. English, Nepali, or mixed input is welcome.</p><section class="clay form-card" style="margin-top:24px"><label class="field-label">Your description</label><textarea id="report" class="textarea" placeholder="You can start wherever feels easiest...">${esc(state.report)}</textarea><p class="field-note">No names or identifying details are required.</p><label class="field-label">District</label><select id="district" class="select">${['Kathmandu','Lalitpur','Bhaktapur','Pokhara','Other district'].map(d=>`<option ${d===state.district?'selected':''}>${d}</option>`).join('')}</select><label class="emergency-option"><input id="emergency-requested" type="checkbox" ${state.emergencyRequested?'checked':''}> <strong>I need immediate help</strong><small>Check this if you or someone else may be in immediate danger. The case will be prioritized for verified support staff.</small></label><div class="form-actions"><button class="btn soft" data-action="category">${icon('arrow_back')} Back</button><button class="btn primary" data-action="chat">Continue ${icon('arrow_forward')}</button></div></section></section></main>`}
function intakeComplete(){return (state.clarifyingQa||[]).length>=5}
function restoreIntakeHistory(){state.messages=(state.clarifyingQa||[]).flatMap(item=>[{from:'ai',text:item.question},{from:'user',text:item.answer}]);if(!intakeComplete()&&state.analysisQuestions[0])state.messages.push({from:'ai',text:state.analysisQuestions[0]})}
function chat(){const messages=state.messages.length?state.messages.map(m=>`<div class="bubble ${m.from}">${esc(m.text)}</div>`).join(''):'<div class="bubble ai">Preparing a few gentle questions…</div>';const remaining=Math.max(0,5-(state.clarifyingQa||[]).length);return `${header()}<main class="page"><div class="eyebrow center">Step 3 of 5 · A few gentle questions</div><div class="chat clay"><div class="chat-scroll" id="chat-scroll">${messages}</div><form class="chat-input" data-form="chat"><input id="chat-input" class="input" placeholder="Type your message..." autocomplete="off" ${intakeComplete()?'disabled':''}/><button class="icon-btn" aria-label="Send" ${intakeComplete()?'disabled':''}>${icon('send')}</button></form>${intakeComplete()?`<button class="btn primary full" style="margin-top:14px" data-action="summary">Continue to rights summary ${icon('arrow_forward')}</button>`:`<p class="field-note" style="margin-top:14px">${remaining} more question${remaining===1?'':'s'} before the next step.</p>`}</div></main>`}
function summary(){return `${header()}<main class="page narrow">${progress(2)}<div class="eyebrow">Step 3 of 5 · Your first overview</div><h1 class="headline">What this may mean</h1><p class="subhead">This is general legal information, grounded in Nepal's support pathways. It is not formal legal advice.</p><div class="summary-grid" style="margin-top:24px"><section class="clay panel"><h2>${icon('gavel')} Your options</h2><div class="legal-list"><div class="legal-item">${icon('info')}<div><strong>Plain-language guidance</strong><br><span>${esc(state.aiLegalSummary || 'Your guidance will appear after the report is analyzed.')}</span></div></div><div class="legal-item">${icon('description')}<div><strong>Keep a private record</strong><br><span>Save messages, dates, and details somewhere safe.</span></div></div></div></section><aside class="severity ${state.emergencyRequested?'emergency':''}"><span>${icon(state.emergencyRequested?'warning':'priority_high')} ${state.emergencyRequested?'Immediate help requested':'Safety signal'}</span><strong>${esc(state.severity || 'Pending')}</strong><p>${state.emergencyRequested?'Your request will be prioritized for verified support staff. If danger is immediate, call Nepal Police at 100 or Khabar Garaun at 1145.':'If you are in immediate danger, call Nepal Police at 100 or Khabar Garaun at 1145.'}</p></aside></div><div class="form-actions"><button class="btn primary" data-action="evidence">Continue to evidence ${icon('arrow_forward')}</button></div></main>`}
function evidence(){return `${header()}<main class="page"><div class="eyebrow">Step 4 of 5 · Optional</div><h1 class="headline">Upload evidence</h1><p class="subhead">Add screenshots, documents, photos, or audio now. You can also add them later.</p><div class="summary-grid" style="margin-top:24px"><label class="drop" id="drop"><input id="file-input" type="file" multiple hidden accept="image/jpeg,image/png,image/webp,application/pdf,audio/mpeg,audio/wav,audio/ogg,text/plain"/><div>${icon('cloud_upload')}<h2>Drop files here</h2><p>or click to browse · JPG, PNG, PDF, MP3, WAV, OGG, TXT · size limit applies</p><button type="button" class="btn primary" data-action="browse">Select files</button></div></label><section class="clay panel"><h2>Files in your vault <span class="status">${state.files.length} files</span></h2><div class="files">${state.files.length?state.files.map(f=>`<div class="file">${icon(f.type?.startsWith('audio')?'audio_file':f.type==='application/pdf'?'description':'image')}<span class="file-name">${esc(f.name)}</span></div>`).join(''):'<div class="empty">No evidence added yet.</div>'}</div></section></div><div class="form-actions"><button class="btn soft" data-action="summary">${icon('arrow_back')} Back</button><button class="btn primary" data-action="matches">See support matches ${icon('arrow_forward')}</button></div></main>`}
function matches(){return `${header()}<main class="page"><div class="eyebrow">Step 5 of 5 · Based on ${esc(state.district)}</div><h1 class="headline">Choose where to send your case</h1><p class="subhead">These verified organizations match your needs or region. Nothing is sent without admin review.</p><div class="matches" style="margin-top:24px">${state.matches.map(o=>`<article class="org clay"><div class="org-icon">${icon('handshake')}</div><h3>${esc(o.name)}</h3><p>${esc(o.description)}</p><div class="org-meta">${icon('location_on')}${esc((o.districts||[]).join(' · '))}</div><div class="org-meta">${icon('phone_in_talk')}${esc(o.contact_phone)}</div><button class="btn soft full" data-action="refer" data-ngo-id="${esc(o.id)}">Send to NGO</button></article>`).join('')||'<div class="empty">No verified organization matches this case yet.</div>'}</div><div class="warning">${icon('info')}<span>You can also call <strong>1145</strong>, Nepal's national women's helpline, for immediate support and referrals.</span></div><div class="form-actions"><button class="btn primary" data-action="confirm">Create my Case ID ${icon('arrow_forward')}</button></div></main>`}
function referralForm(){const ngo=state.matches.find(item=>String(item.id)===String(state.selectedNgoId));return `${header()}<main class="page narrow"><div class="eyebrow">Consent to send</div><h1 class="headline">Before sending to ${esc(ngo?.name)}</h1><form data-form="referral"><input type="hidden" id="ref-ngo" value="${esc(state.selectedNgoId)}"><label>What may be shared<select id="ref-scope"><option value="contact_details_evidence_summary">Contact details and evidence summary only</option><option value="full_case">Full case</option></select></label><label>Optional message<textarea id="ref-message" maxlength="5000"></textarea></label><label class="checkbox"><input id="ref-includes-evidence" type="checkbox"> Include the evidence files currently in my vault</label><label class="checkbox"><input id="ref-consent" type="checkbox"> I give explicit consent to send this case. I understand an admin must approve it before the NGO receives anything.</label><button class="btn primary" type="submit">Send case ${icon('arrow_forward')}</button></form></main>`}
function adminPortal(){return `${header()}<main class="page"><div class="eyebrow">Platform administration</div><h1 class="headline">Admin operations</h1><p class="subhead">Review NGO registrations, prioritize emergencies, and monitor case progress.</p><section class="clay panel"><form data-form="admin-login"><input id="admin-token" class="input" type="password" placeholder="Admin token" required><button class="btn primary">Open admin console</button></form></section><div id="admin-console"></div><div id="admin-queue"></div></main>`}
function ngoPortal(){return `${header()}<main class="page"><div class="eyebrow">Verified support organization</div><h1 class="headline">NGO operations</h1><p class="subhead">Register your organization or sign in to manage consented referrals.</p><div class="summary-grid"><section class="clay panel"><h2>NGO login</h2><form data-form="ngo-login"><input id="ngo-token" class="input" type="password" placeholder="NGO access token" required><button class="btn primary">Open dashboard</button></form></section><section class="clay panel"><h2>Register organization</h2><form data-form="ngo-register"><input id="reg-name" class="input" placeholder="Organization name" required><input id="reg-phone" class="input" placeholder="Contact phone" required><input id="reg-email" class="input" type="email" placeholder="Contact email"><input id="reg-website" class="input" type="url" placeholder="Website (optional)"><input id="reg-categories" class="input" placeholder="Categories, comma separated" required><input id="reg-districts" class="input" placeholder="Districts, comma separated" required><textarea id="reg-description" class="textarea" placeholder="Describe your services" required></textarea><button class="btn soft">Submit registration</button></form><div id="ngo-registration-result"></div></section></div><div id="ngo-console"></div><div id="ngo-queue"></div></main>`}
function referralStatus(){return `${header(true)}<main class="page"><h1 class="headline">Referral status</h1><p class="subhead">Your requests remain under your Case ID.</p><div class="matches">${state.referrals.map(item=>`<article class="clay panel"><h3>${esc(item.ngo_name)}</h3><p>Status: <strong>${esc(item.status)}</strong></p><p>Scope: ${esc(item.consent_scope)}</p></article>`).join('')||'<div class="empty">No referral requests yet.</div>'}</div></main>`}
function confirmation(){return `${header()}<main class="page narrow center"><div class="clay id-box">${icon('check_circle')}<h1 class="headline">Your Case ID is ready</h1><p class="subhead">This ID is the only way to access your saved records. We do not link it to your name or email.</p><div class="case-id inset" id="case-id">${esc(state.caseId)}</div><div class="form-actions" style="justify-content:center"><button class="btn primary" data-action="copy">${icon('content_copy')} Copy ID</button><button class="btn soft" data-action="download">${icon('download')} Download</button></div><div class="warning">${icon('info')}<span>Store this ID somewhere safe. If it is lost, we cannot recover your records.</span></div><button class="btn primary" data-action="dashboard">Go to my vault ${icon('arrow_forward')}</button></div></main>`}
function dashboard(){const timeline=state.timeline.map(e=>`<div class="event"><time>${esc(e.date)}</time><h3>${esc(e.summary)}</h3><p>${esc(e.type||'Evidence')}</p></div>`).join('');return `${header(true)}<main class="page"><div class="status">${icon('verified_user')} Vault secured · Live backend data</div><div class="dashboard-grid" style="margin-top:24px"><section class="clay panel"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h2>Recent report</h2><span class="status">${esc(state.status)}</span></div><div class="report-row"><div><strong>${esc(categories.find(c=>c[0]===state.category)?.[2]||'Incident report')}</strong><br><small>${esc(state.district)} · Anonymous report</small></div>${icon('description')}</div><p style="color:var(--muted)">${esc(state.report)}</p><button class="btn soft" data-action="status">${icon('check_circle')} Mark NGO contacted</button></section><section class="severity"><span>${icon('priority_high')} Safety signal</span><strong>${esc(state.severity)}</strong><p>If you are in immediate danger, call Nepal Police at 100 or Khabar Garaun at 1145.</p><button class="btn soft full" data-action="legal-guidance">View legal guidance</button></section><section class="clay panel"><h2>${icon('timeline')} Evidence timeline</h2><div class="timeline">${timeline||'<div class="empty">No evidence timeline yet.</div>'}</div><button class="btn primary" data-action="evidence">Add evidence ${icon('add')}</button></section><section class="clay panel"><h2>${icon('handshake')} Best support match</h2>${state.matches.slice(0,1).map(o=>`<div class="report-row"><div><strong>${esc(o.name)}</strong><br><small>${esc(o.contact_phone)}</small></div>${icon('arrow_forward')}</div>`).join('')}<button class="btn soft full" data-action="matches">View match details</button></section></div></main>`}
function render(screen=state.screen){state.screen=screen;const views={landing,retrieve,category,report,chat,summary,evidence,matches,referralForm,referralStatus,confirmation,adminPortal,ngoPortal,adminDashboardPortal,ngoDashboardPortal,donate,crowdfunding,crowdfundingCampaign,dashboard:resilientDashboardWithHistory};app.innerHTML=views[screen]();window.scrollTo(0,0);const sc=document.querySelector('#chat-scroll');if(sc)sc.scrollTop=sc.scrollHeight;if(screen==='dashboard'&&state.caseId)window.setTimeout(()=>loadThread(state.caseId,'survivor'),0)}
async function analyze(){let data;if(!state.caseId){data=await api('/cases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({category:state.category,district:state.district,initial_report:state.report,clarifying_qa:[],emergency_requested:state.emergencyRequested})});Object.assign(state,{caseId:data.case_id,status:data.status,emergencyRequested:!!data.emergency_requested,analysisStatus:data.analysis_status||'pending',matches:data.matches||[],timeline:data.timeline||[],clarifyingQa:data.clarifying_qa||[],sessionToken:data.session_token||'',isAuthenticated:!!data.session_token,backend:true})}else{const question=[...state.messages].reverse().find(m=>m.from==='ai')?.text;const answer=[...state.messages].reverse().find(m=>m.from==='user')?.text;if(!question||!answer)throw new Error('Please answer the current question before continuing.');data=await api(`/cases/${state.caseId}/clarify`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,answer})});state.clarifyingQa=data.clarifying_qa||[]}state.aiLegalSummary=data.ai_legal_summary;state.severity=data.severity;state.analysisQuestions=data.clarifying_questions||data.next_questions||[];if(!state.messages.length)state.messages=[{from:'ai',text:state.analysisQuestions[0]||'Thank you for sharing.'}];else if(state.analysisQuestions[0])state.messages.push({from:'ai',text:state.analysisQuestions[0]});render('chat')}
async function uploadEvidence(file){const controller=new AbortController();uploadControllers.add(controller);try{return await api(`/cases/${state.caseId}/evidence?regenerate_timeline=false`,{method:'POST',body:(()=>{const form=new FormData();form.append('file',file);form.append('description',file.name);return form})(),signal:controller.signal})}finally{uploadControllers.delete(controller)}}
async function regenerateTimeline(){const data=await api(`/cases/${state.caseId}/timeline`,{method:'POST'});state.timeline=data.timeline||state.timeline;state.analysisStatus=data.analysis_status||'unavailable';return data}
async function ensureCase(){if(state.caseId){if(!state.sessionToken)await authenticate(state.caseId);return}const data=await api('/cases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({category:state.category,district:state.district,initial_report:state.report,clarifying_qa:state.messages.filter(m=>m.from==='user').map(m=>({answer:m.text})),emergency_requested:state.emergencyRequested})});Object.assign(state,{caseId:data.case_id,status:data.status,emergencyRequested:!!data.emergency_requested,analysisStatus:data.analysis_status||'pending',aiLegalSummary:data.ai_legal_summary,severity:data.severity,matches:data.matches||[],timeline:data.timeline||[],sessionToken:data.session_token||'',isAuthenticated:!!data.session_token,backend:true});if(!state.sessionToken)await authenticate(data.case_id);for(const file of state.pendingFiles){const uploaded=await uploadEvidence(file);state.files=state.files.map(item=>item.name===file.name?{...item,id:uploaded.evidence.id}:item)}state.pendingFiles=[];if(state.files.length)await regenerateTimeline()}
async function loadCase(id){await authenticate(id);const data=await api(`/cases/${id}`);Object.assign(state,{caseId:data.case_id,category:data.category,district:data.district,report:data.initial_report,status:data.status,emergencyRequested:!!data.emergency_requested,analysisStatus:data.analysis_status||'pending',aiLegalSummary:data.ai_legal_summary,severity:data.severity,matches:data.matches||[],files:(data.evidence||[]).map(e=>({name:e.name,type:e.type,id:e.id})),timeline:data.timeline||[],clarifyingQa:data.clarifying_qa||[],backend:true});state.referrals=await api(`/cases/${state.caseId}/referrals`);render('dashboard');loadThread(state.caseId,'survivor')}
document.addEventListener('click',e=>{if(!e.target.closest('[data-action="legal-guidance"]'))return;e.stopImmediatePropagation();render('summary')});
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');const action=target?.dataset.action;if(e.target.closest('[data-category]')){state.category=e.target.closest('[data-category]').dataset.category;render('category');return}if(e.target.closest('[data-remove]'))return;if(!action)return;try{if(action==='sos')return openSos();if(action==='close-sos')return closeSos();if(action==='home')return render('landing');if(action==='retrieve')return render('retrieve');if(action==='category')return render('category');if(action==='report'){if(!state.category)return toast('Choose a category first');return render('report')}if(action==='chat'){state.report=document.querySelector('#report')?.value.trim()||'';state.district=document.querySelector('#district')?.value||'Kathmandu';state.emergencyRequested=!!document.querySelector('#emergency-requested')?.checked;if(!state.report)return toast('Add a short description first');state.messages=[];render('chat');return await analyze()}if(action==='summary')return render('summary');if(action==='evidence')return render('evidence');if(action==='matches'){await ensureCase();state.matches=(await api(`/cases/${state.caseId}/matches`))||[];return render('matches')}if(action==='refer'){state.selectedNgoId=target.dataset.ngoId;return render('referralForm')}if(action==='confirm'){return render('confirmation')}if(action==='dashboard'){state.referrals=await api(`/cases/${state.caseId}/referrals`);return render('dashboard')}if(action==='referrals'){state.referrals=await api(`/cases/${state.caseId}/referrals`);return render('referralStatus')}if(action==='copy'){await navigator.clipboard?.writeText(state.caseId);return toast('Case ID copied')}if(action==='download'){const blob=new Blob([`VaultVoice Case ID: ${state.caseId}\nKeep this ID safe.`],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='vaultvoice-case-id.txt';a.click();return}if(action==='browse')return document.querySelector('#file-input')?.click();if(action==='status'){const data=await api(`/cases/${state.caseId}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'ngo_contacted'})});state.status=data.status;return render('dashboard')}if(action==='exit')return handleQuickExit();if(action==='open-case'){const id=document.querySelector('#retrieve-id')?.value.trim().toUpperCase();if(!id)return toast('Enter your Case ID first');return await loadCase(id)}}catch(error){toast(error.message)}});
document.addEventListener('submit',async e=>{if(e.target.dataset.form!=='sos')return;e.preventDefault();const button=e.target.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Sending SOS…';try{const wantsLocation=!!document.querySelector('#sos-location')?.checked;const location=wantsLocation?await currentLocation():null;const data=await api('/sos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({case_id:state.caseId||null,note:document.querySelector('#sos-note')?.value.trim()||null,location_sharing_enabled:wantsLocation,...(location||{})})});state.sosId=data.id;state.sosToken=data.access_token;try{sessionStorage.setItem('vaultvoice-sos',JSON.stringify({id:data.id,token:data.access_token}))}catch(_error){}closeSos();toast(location?'SOS sent with your location. A responder has been alerted.':'SOS sent. Your location was unavailable, but help has been alerted.')}catch(error){button.disabled=false;button.innerHTML=`${icon('warning')} Send SOS now`;toast(error.message)}});
document.addEventListener('submit',async e=>{if(e.target.dataset.form==='referral'){e.preventDefault();if(!document.querySelector('#ref-consent')?.checked)return toast('Please confirm consent');try{const includeEvidence=!!document.querySelector('#ref-includes-evidence')?.checked;const data=await api(`/cases/${state.caseId}/referrals`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ngo_id:Number(document.querySelector('#ref-ngo').value),consent_scope:document.querySelector('#ref-scope').value,submitted_message:document.querySelector('#ref-message').value,consent_confirmed:true,includes_evidence:includeEvidence,evidence_refs:includeEvidence?state.files.map(item=>item.id).filter(Boolean):[]})});state.referrals=[data,...state.referrals];toast('Referral request submitted for admin review');render('referralStatus')}catch(error){toast(error.message)}}});
document.addEventListener('submit',async e=>{if(e.target.dataset.form==='admin-login'){e.preventDefault();const token=document.querySelector('#admin-token').value;const response=await fetch(`${API}/admin/referrals`,{headers:{'X-Admin-Token':token}});if(!response.ok)return toast('Admin authentication failed');const items=await response.json();document.querySelector('#admin-queue').innerHTML=items.map(item=>`<article class="clay panel"><h3>${esc(item.ngo_name)} · ${esc(item.case.case_id)}</h3><p>${esc(item.case.severity||'Pending')} · ${esc(item.case.category)} · ${esc(item.case.district)}</p><p>Scope: ${esc(item.consent_scope)}</p><p>${esc(item.submitted_message||'No message')}</p><button class="btn primary" data-admin-action="approve" data-referral-id="${esc(item.id)}">Approve and forward</button><button class="btn soft" data-admin-action="reject" data-referral-id="${esc(item.id)}">Reject</button></article>`).join('')||'<div class="empty">Queue is clear.</div>';return}if(e.target.dataset.form==='ngo-login'){e.preventDefault();const token=document.querySelector('#ngo-token').value;const response=await fetch(`${API}/ngo/profile`,{headers:{'X-NGO-Token':token}});if(!response.ok)return toast('NGO authentication failed');const profile=await response.json();state.ngoToken=token;state.ngoId=profile.id;state.ngoOrganizationName=profile.name;window.location.assign('/ngo/dashboard')}});
document.addEventListener('submit',async e=>{const id=e.target.dataset.ngoSupport;if(!id)return;e.preventDefault();const response=await fetch(`${API}/ngo/referrals/${id}/support-status`,{method:'PATCH',headers:{'X-NGO-Token':state.ngoToken,'Content-Type':'application/json'},body:JSON.stringify({support_status:e.target.querySelector('input').value})});if(!response.ok)return toast('Support status update failed');e.target.closest('.panel').querySelector('p').textContent='Support status updated';});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-admin-action]');if(button){const token=document.querySelector('#admin-token')?.value||state.adminToken;if(!token)return toast('Admin authentication required');const action=button.dataset.adminAction;try{const response=await fetch(`${API}/admin/referrals/${button.dataset.referralId}/${action}`,{method:'POST',headers:{'X-Admin-Token':token,'Content-Type':'application/json'},body:action==='reject'?JSON.stringify({reason:'Not approved by admin review'}):undefined});if(!response.ok){const detail=await response.json().catch(()=>({}));return toast(detail.detail||'Admin action failed')}toast(action==='approve'?'Referral approved and forwarded.':'Referral declined.');const legacyLogin=document.querySelector('[data-form="admin-login"]');if(legacyLogin)return legacyLogin.requestSubmit();if(document.querySelector('.portal-shell')){portalView='referrals';return renderPortal('admin')}}catch(error){toast(error.message)}return}const ngoButton=e.target.closest('[data-ngo-action]');if(ngoButton){const action=ngoButton.dataset.ngoAction;if(action==='open')return toast('Scoped case details are available through the protected referral API');const response=await fetch(`${API}/ngo/referrals/${ngoButton.dataset.referralId}/${action}`,{method:'POST',headers:{'X-NGO-Token':state.ngoToken,'Content-Type':'application/json'},body:action==='refuse'?JSON.stringify({reason:'NGO declined this referral'}):undefined});if(!response.ok)return toast('NGO action failed');document.querySelector('[data-form="ngo-login"]').requestSubmit()}});
document.addEventListener('submit',async e=>{if(e.target.dataset.form!=='chat')return;e.preventDefault();const input=document.querySelector('#chat-input');const text=input?.value.trim();if(!text)return;state.messages.push({from:'user',text});input.value='';render('chat');try{await analyze()}catch(error){toast(error.message)}});
let portalPollTimer=null;
let knownEmergencyIds=new Set();
function playEmergencyAlert(){try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;const context=new AudioContext();const oscillator=context.createOscillator();const gain=context.createGain();oscillator.type='sawtooth';oscillator.frequency.value=880;gain.gain.value=0.08;oscillator.connect(gain);gain.connect(context.destination);oscillator.start();oscillator.frequency.exponentialRampToValueAtTime(440,context.currentTime+0.35);oscillator.stop(context.currentTime+0.45);setTimeout(()=>context.close?.(),700)}catch(_error){/* browsers may block audio until interaction */}}
function emergencyBadge(item){return item.emergency_requested||item.severity==='urgent'?'<span class="emergency-badge">IMMEDIATE HELP</span>':''}
async function loadNgoConsole(token, alertNew=true){const response=await fetch(`${API}/ngo/dashboard`,{headers:{'X-NGO-Token':token}});if(!response.ok)return toast('NGO authentication failed');const data=await response.json();const emergencies=(data.referrals||[]).filter(item=>item.emergency_requested||item.severity==='urgent');if(alertNew){const fresh=emergencies.filter(item=>!knownEmergencyIds.has(item.id));if(fresh.length)playEmergencyAlert()}knownEmergencyIds=new Set(emergencies.map(item=>item.id));const profile=data.organization||{};document.querySelector('#ngo-console').innerHTML=`<section class="clay panel"><div class="portal-head"><div><h2>${esc(profile.name||'NGO dashboard')}</h2><p>${esc(profile.verification_status||'approved')} · ${esc(data.subscription_tier||'free')} plan</p></div><div class="alert-count">${emergencies.length} urgent</div></div><div class="metrics"><strong>${data.referrals?.length||0}<small>Active referrals</small></strong><strong>${data.emergency_count||0}<small>Immediate help</small></strong><strong>${data.metrics?.average_response_time_hours??'—'}<small>Avg. hours</small></strong></div></section><section class="portal-list">${(data.referrals||[]).map(item=>`<article class="clay panel ${item.emergency_requested?'urgent-card':''}"><div class="portal-head"><h3>${emergencyBadge(item)} ${esc(item.ngo_name)} · ${esc(item.case_id)}</h3><span>${esc(item.status)}</span></div><p>${esc(item.consent_scope)} · ${esc(item.case_status||'pending')}</p><p>Severity: ${esc(item.severity||'pending')}</p><div class="inline-actions"><select data-ngo-status="${esc(item.id)}"><option value="pending" ${item.case_status==='pending'?'selected':''}>Pending</option><option value="processing" ${item.case_status==='processing'?'selected':''}>Processing</option><option value="completed" ${item.case_status==='completed'?'selected':''}>Completed</option></select>${item.status==='forwarded'?`<button class="btn primary" data-ngo-action="acknowledge" data-referral-id="${esc(item.id)}">Acknowledge</button><button class="btn soft" data-ngo-action="refuse" data-referral-id="${esc(item.id)}">Refuse</button>`:''}</div><form data-ngo-note="${esc(item.id)}" class="inline-actions"><input placeholder="Add a case note" required><button class="btn soft">Save note</button></form></article>`).join('')||'<div class="empty">No forwarded referrals.</div>'}</section>`;if(!portalPollTimer)portalPollTimer=setInterval(()=>loadNgoConsole(token,true),10000)}
async function loadAdminConsole(token){state.adminToken=token;const headers={'X-Admin-Token':token};const [ngosResponse,casesResponse,referralsResponse]=await Promise.all([fetch(`${API}/admin/ngos`,{headers}),fetch(`${API}/admin/cases`,{headers}),fetch(`${API}/admin/referrals`,{headers})]);if(!ngosResponse.ok||!casesResponse.ok||!referralsResponse.ok)return toast('Admin authentication failed');const ngos=await ngosResponse.json();const cases=await casesResponse.json();const referrals=await referralsResponse.json();const emergencies=cases.filter(item=>item.emergency_requested||item.severity==='urgent');if(emergencies.some(item=>!knownEmergencyIds.has(item.case_id)))playEmergencyAlert();knownEmergencyIds=new Set(emergencies.map(item=>item.case_id));document.querySelector('#admin-console').innerHTML=`<section class="clay panel"><div class="portal-head"><h2>Emergency queue</h2><span class="alert-count">${emergencies.length}</span></div>${emergencies.map(item=>`<article class="urgent-row"><strong>${esc(item.case_id)}</strong> · ${esc(item.category)} · ${esc(item.district)}<span>${esc(item.severity||'pending')}</span></article>`).join('')||'<div class="empty">No emergency cases.</div>'}</section><section class="clay panel"><h2>NGO registrations</h2>${ngos.map(item=>`<article class="portal-row"><div><strong>${esc(item.name)}</strong><p>${esc(item.verification_status)} · ${esc((item.districts||[]).join(', '))}</p></div>${item.verification_status==='pending'?`<button class="btn primary" data-admin-ngo="approve" data-ngo-id="${item.id}">Approve</button><button class="btn soft" data-admin-ngo="reject" data-ngo-id="${item.id}">Reject</button>`:''}</article>`).join('')}</section><section class="clay panel"><h2>All cases</h2>${cases.map(item=>`<article class="portal-row ${item.emergency_requested?'urgent-row':''}"><div><strong>${emergencyBadge(item)} ${esc(item.case_id)}</strong><p>${esc(item.category)} · ${esc(item.district)} · ${esc(item.status)}</p></div><select data-admin-case-status="${esc(item.case_id)}"><option value="open" ${item.status==='open'?'selected':''}>Open</option><option value="ngo_contacted" ${item.status==='ngo_contacted'?'selected':''}>NGO contacted</option><option value="resolved" ${item.status==='resolved'?'selected':''}>Resolved</option></select></article>`).join('')}</section><section class="clay panel"><h2>Referral approvals</h2>${referrals.map(item=>`<article class="portal-row"><div><strong>${esc(item.case_id)} · ${esc(item.ngo_name)}</strong><p>${esc(item.case?.severity||'pending')} · ${esc(item.consent_scope)}</p></div><button class="btn primary" data-admin-action="approve" data-referral-id="${esc(item.id)}">Approve and forward</button><button class="btn soft" data-admin-action="reject" data-referral-id="${esc(item.id)}">Reject</button></article>`).join('')||'<div class="empty">No referrals awaiting review.</div>'}</section>`;if(!portalPollTimer)portalPollTimer=setInterval(()=>loadAdminConsole(token),10000)}
async function loadAdminInsights(token){const response=await fetch(`${API}/admin/ngo-activity`,{headers:{'X-Admin-Token':token}});if(!response.ok)return;const activity=await response.json();const target=document.querySelector('#admin-console');if(!target)return;target.insertAdjacentHTML('beforeend',`<section class="clay panel"><h2>NGO activity</h2>${activity.map(item=>`<article class="portal-row"><div><strong>${esc(item.ngo_name)}</strong><p>${esc(item.verification_status)} · ${item.total_referrals} referrals</p></div><span>${item.pending} pending · ${item.processing} processing · ${item.completed} completed</span></article>`).join('')||'<div class="empty">No NGO activity yet.</div>'}</section>`)}
document.addEventListener('submit',async e=>{if(e.target.dataset.form==='ngo-register'){e.preventDefault();const response=await fetch(`${API}/ngo/registrations`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:document.querySelector('#reg-name').value,categories:document.querySelector('#reg-categories').value.split(',').map(x=>x.trim()).filter(Boolean),districts:document.querySelector('#reg-districts').value.split(',').map(x=>x.trim()).filter(Boolean),contact_phone:document.querySelector('#reg-phone').value,contact_email:document.querySelector('#reg-email').value||null,description:document.querySelector('#reg-description').value})});const result=await response.json().catch(()=>({}));if(!response.ok)return toast(result.detail||'Registration failed');document.querySelector('#ngo-registration-result').innerHTML=`<div class="warning"><strong>Save this access token</strong><br><code>${esc(result.token)}</code><br><small>It is inactive until admin approval. After approval, use this token to sign in.</small></div>`;toast('Registration submitted for admin review');e.target.reset();return}if(e.target.dataset.form==='admin-login'){e.preventDefault();const token=document.querySelector('#admin-token').value;await loadAdminConsole(token);return loadAdminInsights(token)}if(e.target.dataset.form==='ngo-login'){e.preventDefault();state.ngoToken=document.querySelector('#ngo-token').value;return loadNgoConsole(state.ngoToken,false)}});
document.addEventListener('change',async e=>{const referralId=e.target.dataset.ngoStatus;if(referralId){const response=await fetch(`${API}/ngo/referrals/${referralId}/case-status`,{method:'PATCH',headers:{'X-NGO-Token':state.ngoToken,'Content-Type':'application/json'},body:JSON.stringify({case_status:e.target.value})});if(!response.ok)return toast('Case status update failed');toast('Case status updated');return}const caseId=e.target.dataset.adminCaseStatus;if(caseId){const response=await fetch(`${API}/admin/cases/${caseId}/status`,{method:'PATCH',headers:{'X-Admin-Token':state.adminToken,'Content-Type':'application/json'},body:JSON.stringify({status:e.target.value})});if(!response.ok)return toast('Case status update failed');toast('Case status updated')}});
document.addEventListener('submit',async e=>{const referralId=e.target.dataset.ngoNote;if(!referralId)return;e.preventDefault();const response=await fetch(`${API}/ngo/referrals/${referralId}/notes`,{method:'POST',headers:{'X-NGO-Token':state.ngoToken,'Content-Type':'application/json'},body:JSON.stringify({note:e.target.querySelector('input').value})});if(!response.ok)return toast('Could not save note');e.target.reset();toast('Note saved')});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-admin-ngo]');if(!button)return;const action=button.dataset.adminNgo;try{const response=await fetch(`${API}/admin/ngos/${button.dataset.ngoId}/${action}`,{method:'POST',headers:{'X-Admin-Token':state.adminToken,'Content-Type':'application/json'},body:JSON.stringify({note:action==='reject'?'Rejected during admin review':'Approved during admin review'})});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).detail||'NGO review failed');const result=await response.json();if(result.token)toast(`Approved. NGO token: ${result.token}`);if(document.querySelector('.portal-shell')){portalView='ngos';renderPortal('admin')}else await loadAdminConsole(state.adminToken)}catch(error){toast(error.message)}});
document.addEventListener('change',async e=>{if(e.target.id==='file-input'){if(uploadInFlight)return;uploadInFlight=true;const selected=[...e.target.files];for(const file of selected)state.files.push({name:file.name,size:file.size,type:file.type});try{if(state.caseId){for(const file of selected)await uploadEvidence(file);await regenerateTimeline()}else state.pendingFiles.push(...selected)}catch(error){if(error.name!=='AbortError')toast(error.message)}finally{uploadInFlight=false;e.target.value='';render('evidence')}} });
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),3000)}

let portalView = 'overview';
let portalData = {};
let donationFilters = {};
let threadTimer = null;
function portalHeaders(kind){return kind==='admin'?{'X-Admin-Token':state.adminToken}:kind==='survivor'?{'Authorization':`Bearer ${state.sessionToken}`}:{'X-NGO-Token':state.ngoToken}}
async function portalFetch(path, kind, options={}){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);try{options={...options,signal:controller.signal,headers:{...portalHeaders(kind),...(options.headers||{})}};const response=await fetch(`${API}${path}`,options);if(!response.ok)throw new Error((await response.json().catch(()=>({}))).detail||`Request failed (${response.status})`);return await response.json()}catch(error){if(error.name==='AbortError')throw new Error('The request took too long. Please try again.');throw error}finally{clearTimeout(timeout)}}
function portalNav(kind){const groups=kind==='admin'?[['overview','Overview','dashboard'],['sos','SOS Command','sos'],['cases','All Cases','folder_open'],['ngos','NGO Applications','verified'],['referrals','Referrals','route'],['crowdfunding-requests','Crowdfunding Requests','volunteer_activism'],['campaigns','Crowdfunding Campaigns','campaign'],['donations','Donations','payments'],['messages','Messages','forum'],['settings','Settings / Admin Users','settings']]:[['overview','Overview','dashboard'],['sos','SOS Alerts','sos'],['cases','My Cases','folder_shared'],['messages','Messages','forum'],['profile','Profile / Verification','badge']];return groups.map(([id,label,ic])=>`<button class="portal-link ${portalView===id?'active':''}" data-portal-nav="${id}">${icon(ic)}<span>${label}</span></button>`).join('')}
function portalShell(kind, content=''){const title=kind==='admin'?'Admin workspace':'NGO workspace';const page=portalView==='overview'?'Overview':portalView.replaceAll('-', ' ');return `<div class="portal-shell ${kind}"><aside class="portal-sidebar"><a class="brand" href="/">${icon('security')}<span>VaultVoice</span></a><div class="portal-kicker">${title}</div><nav>${portalNav(kind)}</nav><button class="portal-logout" data-portal-logout>${icon('logout')} Sign out</button></aside><main class="portal-main"><header class="portal-topbar"><div><span class="eyebrow">${kind==='admin'?'Platform operations':esc(state.ngoOrganizationName||'Verified support organization')}</span><div class="portal-breadcrumb">${title} / ${esc(page)}</div><h1>${esc(page)}</h1></div><div class="portal-tools"><span class="status"><span class="online-dot"></span>Live workspace</span>${kind==='ngo'?`<button class="btn soft" data-portal-nav="profile">${icon('badge')} Profile</button>`:''}<button class="btn soft portal-top-logout" data-portal-logout>${icon('logout')} Sign out</button></div></header><div id="portal-content">${content}</div></main></div>`}
function portalLogin(kind){const label=kind==='admin'?'Admin token':'NGO access token';return `<main class="page narrow portal-login"><div class="eyebrow">Protected workspace</div><h1 class="headline">${kind==='admin'?'Admin sign in':'NGO sign in'}</h1><p class="subhead">Use the access token issued for this workspace.</p><section class="clay panel"><form data-form="portal-${kind}-login"><label class="field-label">${label}</label><input id="portal-token" class="input" type="password" required><button class="btn primary full">Open workspace ${icon('arrow_forward')}</button></form></section>${kind==='ngo'?`<section class="clay panel"><h2>New organization?</h2><p class="field-note">Registration stays available from the existing NGO application workflow.</p><a class="btn soft" href="/ngo">Register organization</a></section>`:''}</main>`}
function adminDashboardPortal(){return state.adminToken?portalShell('admin','<div class="loading">Loading workspace...</div>'):portalLogin('admin')}
function ngoDashboardPortal(){return state.ngoToken?portalShell('ngo','<div class="loading">Loading workspace...</div>'):portalLogin('ngo')}
function metric(label,value,accent=''){return `<div class="metric ${accent}"><strong>${esc(value)}</strong><span>${label}</span></div>`}
function statusPill(value){return `<span class="status-pill status-${esc(String(value||'pending').replaceAll('_','-'))}">${esc(String(value||'pending').replaceAll('_',' '))}</span>`}
function adminDonations(data){const query=new URLSearchParams(Object.entries(donationFilters).filter(([,value])=>value));const exportUrl=`${API}/admin/donations/export?${query}`;return `<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Funds</span><h2>Complete donation log</h2></div><strong>${esc(data.total_completed||'0')} completed</strong></div><form class="inline-actions" data-form="donation-filters"><select id="donation-type" class="select"><option value="">All donations</option><option value="platform" ${donationFilters.donation_type==='platform'?'selected':''}>Platform</option><option value="campaign" ${donationFilters.donation_type==='campaign'?'selected':''}>Campaign</option></select><select id="donation-status" class="select"><option value="">All statuses</option><option value="pending" ${donationFilters.status==='pending'?'selected':''}>Pending</option><option value="completed" ${donationFilters.status==='completed'?'selected':''}>Completed</option><option value="failed" ${donationFilters.status==='failed'?'selected':''}>Failed</option><option value="refunded" ${donationFilters.status==='refunded'?'selected':''}>Refunded</option></select><input id="donation-from" class="input" type="date" value="${esc(donationFilters.from_date||'')}"><input id="donation-to" class="input" type="date" value="${esc(donationFilters.to_date||'')}"><button class="btn soft">Filter</button><a class="btn soft" href="${exportUrl}" download>Export CSV</a></form><div class="data-table">${(data.items||[]).map(item=>`<div class="queue-row"><div><strong>${esc(item.donor_name||'Anonymous')}</strong><p>${esc(item.type)} · ${esc(item.campaign_id||'Platform donation')} · ${esc(item.created_at||'')}</p></div><span>${esc(item.currency)} ${esc(item.amount)} · ${statusPill(item.payment_status)}<small>${esc(item.payment_reference||'No payment reference')}</small></span></div>`).join('')||'<div class="empty">No donations match these filters.</div>'}</div></section>`}
async function loadCombinedDonations(){try{const query=new URLSearchParams(Object.entries(donationFilters).filter(([,value])=>value));const data=await portalFetch(`/admin/donations?${query}`,'admin');document.querySelector('#portal-content').innerHTML=adminDonations(data)}catch(error){document.querySelector('#portal-content').innerHTML=`<div class="warning">${esc(error.message)}</div>`}}
function adminOverview(data){return `<div class="metric-grid">${metric('Active SOS',data.active_sos||0,'danger')}${metric('SOS awaiting acknowledgement',data.unacknowledged_sos||0,'danger')}${metric('Open cases',data.open_cases)}${metric('Urgent / unassigned',data.urgent_unassigned,'danger')}${metric('Pending NGO applications',data.pending_ngo_applications)}${metric('Pending referrals',data.pending_referrals)}</div><div class="portal-columns"><section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Monitor</span><h2>Recent activity</h2></div><button class="btn soft" data-portal-nav="sos">Open SOS command ${icon('arrow_forward')}</button></div><div class="activity-list">${(data.recent_activity||[]).map(item=>`<div class="activity-item"><span class="activity-icon">${icon(item.status==='resolved'?'check_circle':'update')}</span><div><strong>${esc(item.case_id)}</strong><p>Status changed to ${esc(item.status)}</p></div><time>${item.updated_at?new Date(item.updated_at).toLocaleString():''}</time></div>`).join('')||'<div class="empty">No activity yet.</div>'}</div></section><section class="clay panel"><span class="eyebrow">Queue health</span><h2>Needs attention</h2><div class="attention-row"><span>SOS awaiting acknowledgement</span><b>${data.unacknowledged_sos||0}</b></div><div class="attention-row"><span>NGO applications</span><b>${data.pending_ngo_applications}</b></div><div class="attention-row"><span>Referrals</span><b>${data.pending_referrals}</b></div></section></div>`}
function sosLocation(item){return item.latitude==null?`<span class="field-note">Location unavailable: ${esc((item.location_status||'not_requested').replaceAll('_',' '))}</span>`:`<a class="btn soft" target="_blank" rel="noopener" href="https://maps.google.com/?q=${encodeURIComponent(`${item.latitude},${item.longitude}`)}">${icon('location_on')} Open location${item.accuracy!=null?` · ±${Math.round(item.accuracy)}m`:''}</a>`}
function adminSos(items,ngos){return `<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Immediate response</span><h2>SOS command center</h2></div><span class="field-note">${items.filter(x=>!['resolved','cancelled'].includes(x.status)).length} active alerts</span></div>${items.map(item=>`<article class="urgent-row"><div class="section-heading"><div><strong>${icon('sos')} SOS · ${esc(item.id.slice(0,8))}</strong><p>${esc(item.note||'No additional note')} · ${item.created_at?new Date(item.created_at).toLocaleString():''}</p></div>${statusPill(item.status)}</div><div class="inline-actions">${sosLocation(item)}<select class="select" data-sos-assignment="${esc(item.id)}"><option value="">Assign verified NGO…</option>${ngos.filter(n=>n.verification_status==='approved').map(n=>`<option value="${n.id}" ${item.assigned_ngo_id===n.id?'selected':''}>${esc(n.name)}</option>`).join('')}</select><button class="btn primary" data-admin-sos="acknowledged" data-sos-id="${esc(item.id)}">Acknowledge</button><button class="btn soft" data-admin-sos="review_requested" data-sos-police="true" data-sos-id="${esc(item.id)}">Police review</button><button class="btn soft" data-admin-sos="contacted" data-sos-police="true" data-sos-id="${esc(item.id)}">Police contacted</button></div><small>Assigned: ${esc(item.assigned_ngo_name||'Unassigned')} · Police: ${esc(item.police_escalation_status)}</small></article>`).join('')||'<div class="empty">No SOS alerts.</div>'}</section>`}
function ngoSos(items){return `<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Immediate response</span><h2>Assigned SOS alerts</h2></div><span class="field-note">${items.filter(x=>!['resolved','cancelled'].includes(x.status)).length} active</span></div>${items.map(item=>`<article class="urgent-row"><div class="section-heading"><div><strong>${icon('sos')} SOS · ${esc(item.id.slice(0,8))}</strong><p>${esc(item.note||'No additional note')}</p></div>${statusPill(item.status)}</div><div class="inline-actions">${sosLocation(item)}<button class="btn primary" data-ngo-sos="acknowledged" data-sos-id="${esc(item.id)}">Acknowledge</button><button class="btn soft" data-ngo-sos="responder_en_route" data-sos-id="${esc(item.id)}">On the way</button><button class="btn soft" data-ngo-sos="survivor_contacted" data-sos-id="${esc(item.id)}">Contacted</button><button class="btn soft" data-ngo-sos="resolved" data-sos-id="${esc(item.id)}">Resolve</button></div></article>`).join('')||'<div class="empty">No SOS alerts assigned to your organization.</div>'}</section>`}
function adminCases(items){return `<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Case management</span><h2>All cases</h2></div><span class="field-note">${items.length} records</span></div><form class="filter-bar" data-form="case-filters"><select id="filter-status"><option value="">All statuses</option><option>open</option><option>ngo_contacted</option><option>resolved</option></select><select id="filter-severity"><option value="">All severity</option><option>urgent</option><option>high</option><option>medium</option><option>low</option></select><select id="filter-category"><option value="">All categories</option>${categories.map(c=>`<option value="${c[0]}">${c[2]}</option>`).join('')}</select><button class="btn soft">Filter</button></form><div class="data-table"><div class="table-row table-head"><span>Case</span><span>Category</span><span>Severity</span><span>Status</span><span>Created</span></div>${items.map(item=>`<button class="table-row table-link ${item.emergency_requested?'row-danger':''}" data-portal-case="${esc(item.case_id)}"><span><strong>${esc(item.case_id)}</strong><small>${esc(item.district)}</small></span><span>${esc(item.category)}</span><span>${statusPill(item.severity||'pending')}</span><span>${statusPill(item.status)}</span><span>${item.created_at?new Date(item.created_at).toLocaleDateString():''}</span></button>`).join('')||'<div class="empty">No cases match these filters.</div>'}</div></section>`}
function adminSimpleList(title, items, fields){return `<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Admin queue</span><h2>${title}</h2></div><span class="field-note">${items.length} items</span></div>${items.map(item=>`<div class="queue-row"><div><strong>${esc(item.ngo_name||item.case_id||item.id)}</strong><p>${esc(item.case?.category||item.category||item.status||'')}</p></div><div class="inline-actions">${statusPill(item.status)}${fields==='referrals'&&item.status!=='closed'?`<button class="btn primary" data-admin-action="approve" data-referral-id="${esc(item.id)}">Approve</button><button class="btn soft" data-admin-action="reject" data-referral-id="${esc(item.id)}">Reject</button>`:''}</div></div>`).join('')||'<div class="empty">Nothing needs attention.</div>'}</section>`}
function adminNgoApplications(items){const pending=items.filter(item=>item.verification_status==='pending').length;return `<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Admin queue</span><h2>NGO applications</h2></div><span class="field-note">${pending} pending · ${items.length} total</span></div>${items.map(item=>`<article class="clay panel" style="margin:14px 0"><div class="section-heading"><div><strong>${esc(item.name)}</strong><p class="field-note">Submitted ${item.created_at?esc(new Date(item.created_at).toLocaleString()):'recently'}</p></div><div>${statusPill(item.verification_status)}</div></div><div class="detail-meta"><span><b>Services:</b> ${esc((item.categories||[]).join(', ')||'Not provided')}</span><span><b>Regions:</b> ${esc((item.districts||[]).join(', ')||'Not provided')}</span></div><p class="field-note"><b>Phone:</b> ${esc(item.contact_phone||'Not provided')} · <b>Email:</b> ${esc(item.contact_email||'Not provided')}${item.website?` · <a href="${esc(item.website)}" target="_blank" rel="noopener noreferrer">Website</a>`:''}</p><p class="preserve">${esc(item.description||'No description provided.')}</p>${item.verification_note?`<div class="warning">${esc(item.verification_note)}</div>`:''}${item.verification_status==='pending'?`<div class="inline-actions"><button class="btn primary" data-admin-ngo="approve" data-ngo-id="${esc(item.id)}">Approve</button><button class="btn soft" data-admin-ngo="reject" data-ngo-id="${esc(item.id)}">Decline</button></div>`:''}</article>`).join('')||'<div class="empty">No NGO applications yet.</div>'}</section>`}
function adminDetail(item){return `<div class="detail-head"><button class="btn soft" data-portal-nav="cases">${icon('arrow_back')} All cases</button><div><span class="eyebrow">Case detail</span><h2>${esc(item.case_id)}</h2></div>${statusPill(item.status)}</div><div class="detail-grid"><section class="clay panel"><h2>Case information</h2><div class="detail-meta"><b>${esc(item.category)}</b><span>${esc(item.district)}</span><span>${statusPill(item.severity||'pending')}</span></div><p class="preserve">${esc(item.initial_report)}</p><div class="inline-actions"><select data-admin-case-status="${esc(item.case_id)}"><option value="open" ${item.status==='open'?'selected':''}>Open</option><option value="ngo_contacted" ${item.status==='ngo_contacted'?'selected':''}>NGO contacted</option><option value="resolved" ${item.status==='resolved'?'selected':''}>Resolved</option></select></div><h3>Timeline</h3><div class="timeline">${(item.timeline||[]).map(e=>`<div class="event"><time>${esc(e.date||'')}</time><h3>${esc(e.summary||e.type||'Update')}</h3></div>`).join('')||'<div class="empty">No timeline entries.</div>'}</div></section><section class="clay panel"><h2>Evidence & documents</h2><p class="field-note">Admin-only access. Every download is audited by the protected API.</p><div class="file-list">${(item.evidence||[]).map(file=>`<div class="queue-row"><span>${icon('description')} ${esc(file.name)}</span><button class="btn soft" data-evidence-case="${esc(item.case_id)}" data-evidence-id="${file.id}">${icon('download')} Download</button></div>`).join('')||'<div class="empty">No evidence uploaded.</div>'}</div><h2>Referral history</h2>${(item.referrals||[]).map(ref=>`<div class="queue-row"><div><strong>${esc(ref.ngo_name)}</strong><p>${esc(ref.consent_scope)} · ${ref.includes_evidence?'Evidence included':'No evidence included'}</p></div>${statusPill(ref.status)}</div>`).join('')||'<div class="empty">No referrals.</div>'}</section></div><section class="clay panel"><h2>Unified case thread</h2><div data-chat-case="${esc(item.case_id)}" data-chat-kind="admin"><div class="loading">Loading messages...</div></div></section></div>`}
function ngoCases(items){return `<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Assigned work</span><h2>My cases</h2></div><span class="field-note">${items.length} cases</span></div><div class="data-table"><div class="table-row table-head"><span>Case</span><span>Category</span><span>Severity</span><span>Case status</span><span>Referral</span></div>${items.map(item=>`<button class="table-row table-link" data-ngo-case="${esc(item.id)}"><span><strong>${esc(item.case_id)}</strong><small>${item.emergency_requested?'Immediate help':''}</small></span><span>${esc(item.case?.category||item.consent_scope)}</span><span>${statusPill(item.severity||'pending')}</span><span>${statusPill(item.case_status)}</span><span>${statusPill(item.status)}</span></button>`).join('')||'<div class="empty">No approved referrals yet.</div>'}</div></section>`}
function ngoDetail(item){const c=item.case||{};return `<div class="detail-head"><button class="btn soft" data-portal-nav="cases">${icon('arrow_back')} My cases</button><div><span class="eyebrow">Case detail</span><h2>${esc(item.case_id)}</h2></div>${statusPill(item.case_status)}</div><div class="detail-grid"><section class="clay panel"><h2>Case summary</h2><div class="detail-meta"><b>${esc(c.category||'Case')}</b><span>${esc(c.district||'')}</span><span>${statusPill(c.severity||item.severity||'pending')}</span></div><p class="preserve">${esc(c.initial_report||'The referral was shared without the full case description.')}</p><label class="field-label">Update case status</label><select class="select" data-ngo-status="${esc(item.id)}"><option value="pending" ${item.case_status==='pending'?'selected':''}>Pending</option><option value="in_progress" ${item.case_status==='in_progress'?'selected':''}>In progress</option><option value="resolved" ${item.case_status==='resolved'?'selected':''}>Resolved</option><option value="on_hold" ${item.case_status==='on_hold'?'selected':''}>On hold</option></select><textarea class="textarea compact" data-ngo-status-note="${esc(item.id)}" placeholder="Optional status note"></textarea><h3>Referral scope</h3><p>${item.includes_evidence?'Evidence was explicitly shared with this referral.':'Evidence was not shared with this referral.'}</p><h3>Evidence</h3>${(c.evidence||[]).map(file=>`<div class="queue-row"><span>${icon('description')} ${esc(file.name)}</span><button class="btn soft" data-ngo-evidence-ref="${esc(item.id)}" data-evidence-id="${file.id}">${icon('download')}</button></div>`).join('')||'<div class="empty">No evidence available under this referral scope.</div>'}</section><section class="clay panel"><h2>Unified case thread</h2><div data-chat-case="${esc(item.case_id)}" data-chat-kind="ngo"><div class="loading">Loading messages...</div></div></section></div>`}
function chatPanel(caseId, kind){return `<div class="thread" id="thread-${esc(caseId)}"><div class="thread-scroll" data-thread-scroll></div><form class="thread-form" data-thread-form="${esc(caseId)}"><input class="input" data-thread-input placeholder="Write a message..." autocomplete="off">${kind==='admin'?`<label class="thread-note"><input type="checkbox" data-thread-internal> Internal note</label>`:''}<button class="icon-btn" aria-label="Send message">${icon('send')}</button></form></div>`}
async function loadThread(caseId, kind){const target=document.querySelector(`[data-chat-case="${CSS.escape(caseId)}"]`);if(!target)return;target.innerHTML=chatPanel(caseId,kind);const refresh=async()=>{try{const messages=await portalFetch(`/cases/${encodeURIComponent(caseId)}/messages`,kind);const scroll=target.querySelector('[data-thread-scroll]');scroll.innerHTML=messages.map(m=>`<div class="thread-message ${m.sender_type==='admin'?'from-admin':m.sender_type==='ngo'?'from-ngo':'from-survivor'}"><div class="thread-label">${m.sender_type==='survivor'?'Survivor':m.sender_type==='ngo'?'NGO':'Admin'}${m.sender_id=== (kind==='ngo'?String(state.ngoId):'')?' · You':''}</div><p>${esc(m.message)}</p><time>${m.sent_at?new Date(m.sent_at).toLocaleString():''}${m.is_internal_note?' · Internal note':''}</time></div>`).join('')||'<div class="empty">No messages yet.</div>';scroll.scrollTop=scroll.scrollHeight}catch(error){target.querySelector('[data-thread-scroll]').innerHTML=`<div class="empty">${esc(error.message)}</div>`}};await refresh();clearInterval(threadTimer);threadTimer=setInterval(refresh,5000)}
async function loadAdminView(){try{if(portalView==='overview')portalData.overview=await portalFetch('/admin/overview','admin');else if(portalView==='cases')portalData.cases=await portalFetch('/admin/cases','admin');else if(portalView==='ngos')portalData.ngos=await portalFetch('/admin/ngos','admin');else if(portalView==='referrals')portalData.referrals=await portalFetch('/admin/referrals','admin');else if(portalView==='crowdfunding-requests')portalData.funding=await portalFetch('/admin/crowdfunding-requests','admin');else if(portalView==='campaigns')portalData.campaigns=await portalFetch('/admin/crowdfunding-campaigns','admin');else if(portalView==='donations')portalData.donations=await portalFetch('/admin/donations','admin');else if(portalView==='settings')portalData.settings=await portalFetch('/admin/settings','admin');const content=portalView==='overview'?adminOverview(portalData.overview):portalView==='cases'?adminCases(portalData.cases||[]):portalView==='ngos'?adminNgoApplications(portalData.ngos||[]):portalView==='referrals'?adminSimpleList('Referral review',portalData.referrals||[],'referrals'):portalView==='crowdfunding-requests'?adminSimpleList('Crowdfunding requests',portalData.funding||[]):portalView==='campaigns'?adminSimpleList('Live and closed campaigns',portalData.campaigns||[]):portalView==='donations'?`<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Funds</span><h2>Donations</h2></div><strong>NPR ${esc(portalData.donations.total_completed||'0')}</strong></div><div class="data-table">${(portalData.donations.items||[]).map(item=>`<div class="queue-row"><span>${esc(item.id)}</span><span>NPR ${esc(item.amount)} · ${statusPill(item.payment_status)}</span></div>`).join('')||'<div class="empty">No donations yet.</div>'}</div></section>`:`<section class="clay panel"><h2>Workspace settings</h2><div class="attention-row"><span>Max upload size</span><b>${Math.round((portalData.settings.max_upload_bytes||0)/1048576)} MB</b></div><div class="attention-row"><span>Rate limit</span><b>${esc(portalData.settings.rate_limit||'')}</b></div></section>`;document.querySelector('#portal-content').innerHTML=content}catch(error){document.querySelector('#portal-content').innerHTML=`<div class="warning">${esc(error.message)}</div>`}}
async function loadNgoView(){try{if(portalView==='overview'){portalData.dashboard=await portalFetch('/ngo/dashboard','ngo');const d=portalData.dashboard;const refs=d.referrals||[];document.querySelector('#portal-content').innerHTML=`<div class="metric-grid">${metric('Pending cases',refs.filter(x=>x.case_status==='pending').length)}${metric('In progress',refs.filter(x=>x.case_status==='in_progress').length,'sage')}${metric('Resolved',refs.filter(x=>x.case_status==='resolved').length)}${metric('Urgent attention',d.emergency_count||0,'danger')}</div><div class="portal-columns"><section class="clay panel"><span class="eyebrow">Latest work</span><h2>Recent cases</h2>${refs.slice(0,5).map(x=>`<div class="queue-row"><div><strong>${esc(x.case_id)}</strong><p>${esc(x.ngo_name)} · ${esc(x.severity||'pending')}</p></div>${statusPill(x.case_status)}</div>`).join('')||'<div class="empty">No approved referrals yet.</div>'}</section><section class="clay panel"><span class="eyebrow">Organization</span><h2>${esc(d.organization?.name||'NGO')}</h2><p>${esc(d.organization?.verification_status||'approved')} · ${esc(d.subscription_tier||'free')} plan</p><button class="btn soft" data-portal-nav="profile">Review profile ${icon('arrow_forward')}</button></section></div>`}else if(portalView==='cases'){portalData.referrals=await portalFetch('/ngo/referrals','ngo');document.querySelector('#portal-content').innerHTML=ngoCases(portalData.referrals)}else if(portalView==='profile'){portalData.profile=await portalFetch('/ngo/profile','ngo');const p=portalData.profile;document.querySelector('#portal-content').innerHTML=`<section class="clay panel profile-form"><span class="eyebrow">Verification</span><h2>${esc(p.name)}</h2><div class="status">${esc(p.verification_status)}</div><form data-form="ngo-profile"><label class="field-label">Specializations</label><input class="input" id="profile-categories" value="${esc((p.categories||[]).join(', '))}"><label class="field-label">Regions</label><input class="input" id="profile-districts" value="${esc((p.districts||[]).join(', '))}"><label class="field-label">Contact phone</label><input class="input" id="profile-phone" value="${esc(p.contact_phone)}"><label class="field-label">Contact email</label><input class="input" id="profile-email" value="${esc(p.contact_email||'')}"><label class="field-label">Description</label><textarea class="textarea">${esc(p.description)}</textarea><button class="btn primary">Save profile and request review</button></form>${p.verification_note?`<div class="warning">${icon('info')} ${esc(p.verification_note)}</div>`:''}</section>`}else{document.querySelector('#portal-content').innerHTML='<section class="clay panel"><h2>Messages</h2><p class="field-note">Open a case to view its shared conversation.</p></section>'}}catch(error){document.querySelector('#portal-content').innerHTML=`<div class="warning">${esc(error.message)}</div>`}}
function ngoOverview(d){const refs=d.referrals||[];const needsResponse=refs.filter(item=>item.status==='forwarded');const active=refs.filter(item=>item.status==='acknowledged'&&item.case_status!=='resolved');const resolved=refs.filter(item=>item.case_status==='resolved');const recent=refs.slice(0,5);return `<div class="metric-grid">${metric('Awaiting response',needsResponse.length,'danger')}${metric('Active support',active.length,'sage')}${metric('Resolved',resolved.length)}${metric('Urgent attention',d.emergency_count||0,'danger')}</div><div class="portal-columns"><section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Priority queue</span><h2>Cases needing attention</h2></div><button class="btn soft" data-portal-nav="cases">View all ${icon('arrow_forward')}</button></div>${recent.map(item=>`<button class="queue-row table-link ${item.emergency_requested?'row-danger':''}" data-ngo-case="${esc(item.id)}"><div><strong>${item.emergency_requested?icon('warning'):icon('folder_shared')} ${esc(item.case_id)}</strong><p>${esc(item.case?.category||item.consent_scope)} · ${esc(item.severity||'pending')}</p></div><div>${statusPill(item.status)} ${statusPill(item.case_status)}</div></button>`).join('')||'<div class="empty">No approved referrals yet.</div>'}</section><section class="clay panel"><span class="eyebrow">Organization status</span><h2>${esc(d.organization?.name||'NGO')}</h2><div class="attention-row"><span>Verification</span>${statusPill(d.organization?.verification_status)}</div><div class="attention-row"><span>Plan</span><b>${esc(d.subscription_tier||'free')}</b></div><div class="attention-row"><span>Assigned referrals</span><b>${refs.length}</b></div><button class="btn soft full" data-portal-nav="profile">Manage organization profile ${icon('arrow_forward')}</button></section></div>`}
function ngoCasesWorkspace(items){const pending=items.filter(item=>item.status==='forwarded').length;return `<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Assigned work</span><h2>My cases</h2></div><span class="field-note">${pending} awaiting response · ${items.length} total</span></div><div class="data-table"><div class="table-row table-head"><span>Case</span><span>Service area</span><span>Priority</span><span>Support status</span><span>Referral</span></div>${items.map(item=>`<button class="table-row table-link ${item.emergency_requested?'row-danger':''}" data-ngo-case="${esc(item.id)}"><span><strong>${esc(item.case_id)}</strong><small>${item.emergency_requested?'Immediate help requested':item.created_at?new Date(item.created_at).toLocaleDateString():''}</small></span><span>${esc(item.case?.category||item.consent_scope)}</span><span>${statusPill(item.severity||'pending')}</span><span>${statusPill(item.case_status)}</span><span>${statusPill(item.status)}</span></button>`).join('')||'<div class="empty">No referrals have been approved for your organization yet.</div>'}</div></section>`}
function ngoDetailWorkspace(item){const c=item.case||{};const canAct=item.status==='forwarded';const active=item.status==='forwarded'||item.status==='acknowledged';return `<div class="detail-head"><button class="btn soft" data-portal-nav="cases">${icon('arrow_back')} My cases</button><div><span class="eyebrow">Case workspace</span><h2>${esc(item.case_id)}</h2></div>${statusPill(item.case_status)}</div>${item.emergency_requested?`<div class="warning">${icon('warning')} Immediate help was requested for this case.</div>`:''}<div class="detail-grid"><section class="clay panel"><h2>Case summary</h2><div class="detail-meta"><b>${esc(c.category||'Case')}</b><span>${esc(c.district||'')}</span>${statusPill(c.severity||item.severity||'pending')}</div><p class="preserve">${esc(c.initial_report||'This referral was shared without the full case description.')}</p><h3>Referral scope</h3><p>${esc(item.consent_scope)} · ${item.includes_evidence?'Evidence was shared with consent.':'No evidence was shared.'}</p>${canAct?`<div class="inline-actions"><button class="btn primary" data-ngo-referral-action="acknowledge" data-referral-id="${esc(item.id)}">Accept and begin support</button><button class="btn soft" data-ngo-referral-action="refuse" data-referral-id="${esc(item.id)}">Decline referral</button></div>`:''}${active?`<form class="inline-actions" data-form="ngo-case-status" data-referral-id="${esc(item.id)}"><select class="select" name="case_status"><option value="pending" ${item.case_status==='pending'?'selected':''}>Pending</option><option value="in_progress" ${item.case_status==='in_progress'?'selected':''}>In progress</option><option value="resolved" ${item.case_status==='resolved'?'selected':''}>Resolved</option><option value="on_hold" ${item.case_status==='on_hold'?'selected':''}>On hold</option></select><input class="input" name="note" placeholder="Optional update note"><button class="btn soft">Save status</button></form>${item.status==='acknowledged'?`<form class="inline-actions" data-form="ngo-support-status" data-referral-id="${esc(item.id)}"><input class="input" name="support_status" value="${esc(item.support_status||'')}" placeholder="Support provided or next step"><button class="btn soft">Save support update</button></form>`:''}`:''}<h3>Evidence</h3>${(c.evidence||[]).map(file=>`<div class="queue-row"><span>${icon('description')} ${esc(file.name)}</span><button class="btn soft" data-ngo-evidence-ref="${esc(item.id)}" data-evidence-id="${file.id}">${icon('download')} Download</button></div>`).join('')||'<div class="empty">No evidence is available under this referral scope.</div>'}</section><section class="clay panel"><h2>Case conversation</h2><p class="field-note">Messages are visible only to the survivor, this NGO, and authorized administrators.</p><div data-chat-case="${esc(item.case_id)}" data-chat-kind="ngo"><div class="loading">Loading messages...</div></div></section></div>`}
async function loadNgoWorkspace(){const target=document.querySelector('#portal-content');if(!target)return;try{if(portalView==='overview'){const dashboard=await portalFetch('/ngo/dashboard','ngo');portalData.dashboard=dashboard;target.innerHTML=ngoOverview(dashboard);return}if(portalView==='cases'){const referrals=await portalFetch('/ngo/referrals','ngo');portalData.referrals=referrals;target.innerHTML=ngoCasesWorkspace(referrals);return}if(portalView==='profile'){const p=await portalFetch('/ngo/profile','ngo');portalData.profile=p;target.innerHTML=`<section class="clay panel profile-form"><span class="eyebrow">Organization profile</span><h2>${esc(p.name)}</h2><div class="detail-meta">${statusPill(p.verification_status)}<span>${esc(p.verification_note||'Keep these details current so referrals reach the right team.')}</span></div><form data-form="ngo-profile"><label class="field-label">Specializations</label><input class="input" id="profile-categories" value="${esc((p.categories||[]).join(', '))}"><label class="field-label">Regions</label><input class="input" id="profile-districts" value="${esc((p.districts||[]).join(', '))}"><label class="field-label">Contact phone</label><input class="input" id="profile-phone" value="${esc(p.contact_phone)}"><label class="field-label">Contact email</label><input class="input" id="profile-email" type="email" value="${esc(p.contact_email||'')}"><label class="field-label">Website</label><input class="input" id="profile-website" type="url" value="${esc(p.website||'')}"><label class="field-label">Services description</label><textarea class="textarea" id="profile-description">${esc(p.description)}</textarea><button class="btn primary">Save organization profile</button></form></section>`;return}target.innerHTML='<section class="clay panel"><span class="eyebrow">Case conversations</span><h2>Messages</h2><p class="field-note">Open a case from My Cases to review its shared conversation and send a secure reply.</p><button class="btn soft" data-portal-nav="cases">Open My Cases</button></section>'}catch(error){target.innerHTML=`<div class="warning">${esc(error.message)}</div>`}}
function ngoParityOverview(d, conversations){const refs=d.referrals||[];const pending=refs.filter(x=>x.case_status==='pending').length;const working=refs.filter(x=>x.case_status==='in_progress').length;const done=refs.filter(x=>x.case_status==='resolved').length;const unread=conversations.reduce((sum,x)=>sum+(x.unread_count||0),0);const activity=[...refs.slice(0,4).map(x=>({icon:x.emergency_requested?'warning':'assignment',title:x.case_id,text:`${x.status.replaceAll('_',' ')} · ${x.case_status.replaceAll('_',' ')}`,date:x.updated_at||x.created_at})),...conversations.filter(x=>x.last_message).slice(0,3).map(x=>({icon:'forum',title:x.case_id,text:`${x.last_sender_type||'New'} message: ${x.last_message}`,date:x.last_message_at}))].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,6);return `<div class="metric-grid ngo-metric-grid">${metric('Pending cases',pending,'danger')}${metric('In progress',working,'sage')}${metric('Resolved',done)}${metric('Unread messages',unread,unread?'danger':'')}</div><div class="portal-columns"><section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Recent activity</span><h2>What needs attention</h2></div><button class="btn soft" data-portal-nav="cases">My Cases ${icon('arrow_forward')}</button></div><div class="activity-list">${activity.map(item=>`<div class="activity-item"><span class="activity-icon">${icon(item.icon)}</span><div><strong>${esc(item.title)}</strong><p>${esc(item.text)}</p></div><time>${item.date?new Date(item.date).toLocaleString():''}</time></div>`).join('')||'<div class="empty">No assigned case activity yet.</div>'}</div></section><section class="clay panel"><span class="eyebrow">Workspace</span><h2>${esc(d.organization?.name||state.ngoOrganizationName||'Your organization')}</h2><div class="attention-row"><span>Verification</span>${statusPill(d.organization?.verification_status)}</div><div class="attention-row"><span>Urgent cases</span><b>${d.emergency_count||0}</b></div><div class="attention-row"><span>Unread messages</span><b>${unread}</b></div><div class="inline-actions"><button class="btn soft" data-portal-nav="messages">Messages</button><button class="btn soft" data-portal-nav="profile">Profile</button></div></section></div>`}
function ngoParityCases(items){return `<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Case management</span><h2>My Cases</h2></div><span class="field-note">${items.length} assigned</span></div><form class="filter-bar" data-form="ngo-case-filters"><input id="ngo-case-search" class="input" placeholder="Search case ID"><select id="ngo-filter-status"><option value="">All support statuses</option><option value="pending">Pending</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="on_hold">On hold</option></select><select id="ngo-filter-severity"><option value="">All priorities</option><option value="urgent">Urgent</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select><select id="ngo-filter-category"><option value="">All service areas</option>${[...new Set(items.map(x=>x.case?.category).filter(Boolean))].map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><button class="btn soft">Filter</button></form><div class="data-table"><div class="table-row table-head"><span>Case</span><span>Service area</span><span>Priority</span><span>Support status</span><span>Assigned</span></div><div id="ngo-case-rows">${ngoCaseRows(items)}</div></div></section>`}
function ngoCaseRows(items){return items.map(item=>`<button class="table-row table-link ${item.emergency_requested?'row-danger':''}" data-ngo-case="${esc(item.id)}"><span><strong>${esc(item.case_id)}</strong><small>${item.emergency_requested?'Immediate help requested':statusPill(item.status)}</small></span><span>${esc(item.case?.category||item.consent_scope)}</span><span>${statusPill(item.severity||'pending')}</span><span>${statusPill(item.case_status)}</span><span>${item.created_at?new Date(item.created_at).toLocaleDateString():''}</span></button>`).join('')||'<div class="empty">No cases match these filters.</div>'}
function ngoParityMessages(items){const unread=items.reduce((sum,x)=>sum+(x.unread_count||0),0);return `<section class="clay panel"><div class="section-heading"><div><span class="eyebrow">Secure conversations</span><h2>Messages</h2></div><span class="field-note">${unread} unread</span></div><div class="data-table"><div class="table-row table-head"><span>Case</span><span>Last message</span><span>From</span><span>Updated</span><span></span></div>${items.map(item=>`<button class="table-row table-link" data-ngo-message-ref="${esc(item.referral_id)}"><span><strong>${esc(item.case_id)}</strong>${item.unread_count?`<small class="unread-count">${item.unread_count} unread</small>`:''}</span><span>${esc(item.last_message||'No messages yet')}</span><span>${esc(item.last_sender_type||'—')}</span><span>${item.last_message_at?new Date(item.last_message_at).toLocaleString():''}</span><span>${icon('arrow_forward')}</span></button>`).join('')||'<div class="empty">No active case conversations yet.</div>'}</div></section>`}
function ngoParityProfile(profile, documents){return `<div class="detail-grid"><section class="clay panel profile-form"><span class="eyebrow">Organization profile</span><h2>${esc(profile.name)}</h2><div class="detail-meta">${statusPill(profile.verification_status)}<span>${esc(profile.verification_note||'Your profile is visible only to authorized platform staff and matched survivors.')}</span></div><form data-form="ngo-profile"><label class="field-label">Specializations</label><input class="input" id="profile-categories" value="${esc((profile.categories||[]).join(', '))}"><label class="field-label">Regions</label><input class="input" id="profile-districts" value="${esc((profile.districts||[]).join(', '))}"><label class="field-label">Contact phone</label><input class="input" id="profile-phone" value="${esc(profile.contact_phone||'')}"><label class="field-label">Contact email</label><input class="input" id="profile-email" type="email" value="${esc(profile.contact_email||'')}"><label class="field-label">Website</label><input class="input" id="profile-website" type="url" value="${esc(profile.website||'')}"><label class="field-label">Services description</label><textarea class="textarea" id="profile-description">${esc(profile.description||'')}</textarea><button class="btn primary">Save organization profile</button></form></section><section class="clay panel"><span class="eyebrow">Verification</span><h2>Documents</h2><div class="file-list">${documents.map(doc=>`<div class="queue-row"><div><strong>${icon('description')} ${esc(doc.name)}</strong><p>${esc(doc.type)} · ${doc.uploaded_at?new Date(doc.uploaded_at).toLocaleDateString():''}</p></div>${statusPill(doc.status)}</div>`).join('')||'<div class="empty">No verification documents have been uploaded.</div>'}</div></section></div>`}
async function loadNgoParityWorkspace(){const target=document.querySelector('#portal-content');if(!target)return;try{if(portalView==='overview'){const [dashboard,conversations]=await Promise.all([portalFetch('/ngo/dashboard','ngo'),portalFetch('/ngo/conversations','ngo')]);portalData.dashboard=dashboard;portalData.conversations=conversations;state.ngoOrganizationName=dashboard.organization?.name||state.ngoOrganizationName;target.innerHTML=ngoParityOverview(dashboard,conversations);return}if(portalView==='cases'){const items=await portalFetch('/ngo/referrals','ngo');portalData.referrals=items;target.innerHTML=ngoParityCases(items);return}if(portalView==='messages'){const items=await portalFetch('/ngo/conversations','ngo');portalData.conversations=items;target.innerHTML=ngoParityMessages(items);return}if(portalView==='profile'){const [profile,documents]=await Promise.all([portalFetch('/ngo/profile','ngo'),portalFetch('/ngo/documents','ngo')]);portalData.profile=profile;target.innerHTML=ngoParityProfile(profile,documents);return}target.innerHTML='<div class="empty">Choose a workspace section.</div>'}catch(error){target.innerHTML=`<div class="warning">${esc(error.message)}</div>`}}
async function openPortal(kind, id){try{const item=kind==='admin'?await portalFetch(`/admin/cases/${encodeURIComponent(id)}`,'admin'):await portalFetch(`/ngo/referrals/${encodeURIComponent(id)}`,'ngo');document.querySelector('#portal-content').innerHTML=kind==='admin'?adminDetail(item):ngoDetailWorkspace(item);if(kind==='admin'||kind==='ngo')loadThread(item.case_id,kind)}catch(error){toast(error.message)}}
async function loadSosPortal(kind){const target=document.querySelector('#portal-content');try{if(kind==='admin'){const [items,ngos]=await Promise.all([portalFetch('/admin/sos','admin'),portalFetch('/admin/ngos','admin')]);target.innerHTML=adminSos(items,ngos)}else target.innerHTML=ngoSos(await portalFetch('/ngo/sos','ngo'))}catch(error){target.innerHTML=`<div class="warning">${esc(error.message)}</div>`}}
function renderPortal(kind){document.querySelector('#portal-content').innerHTML='<div class="loading">Loading...</div>';if(portalView==='sos')return loadSosPortal(kind);kind==='admin'?loadAdminView():loadNgoParityWorkspace()}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-portal-nav]');if(nav){portalView=nav.dataset.portalNav;render(kindFromPath()==='admin'?'adminDashboardPortal':'ngoDashboardPortal');renderPortal(kindFromPath());return}const c=e.target.closest('[data-portal-case]')||e.target.closest('[data-ngo-case]');if(c){openPortal(c.hasAttribute('data-portal-case')?'admin':'ngo',c.dataset.portalCase||c.dataset.ngoCase);return}const logout=e.target.closest('[data-portal-logout]');if(logout){state.adminToken='';state.ngoToken='';clearInterval(threadTimer);render(kindFromPath()==='admin'?'adminDashboardPortal':'ngoDashboardPortal');return}const file=e.target.closest('[data-evidence-case], [data-ngo-evidence-ref]');if(file){const path=file.dataset.evidenceCase?`/admin/cases/${file.dataset.evidenceCase}/evidence/${file.dataset.evidenceId}`:`/ngo/referrals/${file.dataset.ngoEvidenceRef}/evidence/${file.dataset.evidenceId}`;const kind=file.dataset.evidenceCase?'admin':'ngo';try{const response=await fetch(`${API}${path}`,{headers:portalHeaders(kind)});if(!response.ok)throw new Error('Evidence download failed');const blob=await response.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='evidence';a.click();URL.revokeObjectURL(a.href)}catch(error){toast(error.message)}}});
document.addEventListener('submit',async e=>{if(e.target.dataset.form?.startsWith('portal-')){e.preventDefault();const kind=e.target.dataset.form.includes('admin')?'admin':'ngo';const token=e.target.querySelector('#portal-token').value;if(kind==='admin')state.adminToken=token;else{state.ngoToken=token;const p=await fetch(`${API}/ngo/profile`,{headers:{'X-NGO-Token':token}}).then(r=>r.ok?r.json():null);state.ngoId=p?.id||'';state.ngoOrganizationName=p?.name||''}portalView='overview';render(kind==='admin'?'adminDashboardPortal':'ngoDashboardPortal');renderPortal(kind)}if(e.target.dataset.threadForm){e.preventDefault();const kind=e.target.closest('[data-chat-kind]')?.dataset.chatKind||kindFromPath();const id=e.target.dataset.threadForm;const body={message:e.target.querySelector('[data-thread-input]').value,is_internal_note:!!e.target.querySelector('[data-thread-internal]')?.checked};try{await portalFetch(`/cases/${encodeURIComponent(id)}/messages`,kind,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});e.target.reset();toast('Message sent')}catch(error){toast(error.message)}}if(e.target.dataset.form==='ngo-profile'){e.preventDefault();try{await portalFetch('/ngo/profile','ngo',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({categories:document.querySelector('#profile-categories').value.split(',').map(x=>x.trim()).filter(Boolean),districts:document.querySelector('#profile-districts').value.split(',').map(x=>x.trim()).filter(Boolean),contact_phone:document.querySelector('#profile-phone').value,contact_email:document.querySelector('#profile-email').value||null,description:e.target.querySelector('textarea').value})});toast('Profile submitted for review');renderPortal('ngo')}catch(error){toast(error.message)}}});
document.addEventListener('click',e=>{if(e.target.closest('[data-portal-nav="donations"]'))setTimeout(loadCombinedDonations,0)});
document.addEventListener('submit',e=>{if(e.target.dataset.form!=='donation-filters')return;e.preventDefault();donationFilters={donation_type:document.querySelector('#donation-type').value,status:document.querySelector('#donation-status').value,from_date:document.querySelector('#donation-from').value,to_date:document.querySelector('#donation-to').value};loadCombinedDonations()});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-ngo-referral-action]');if(!button)return;e.preventDefault();const action=button.dataset.ngoReferralAction;const id=button.dataset.referralId;try{await portalFetch(`/ngo/referrals/${encodeURIComponent(id)}/${action}`,'ngo',{method:'POST',headers:{'Content-Type':'application/json'},body:action==='refuse'?JSON.stringify({reason:'Unable to take this referral at this time.'}):undefined});toast(action==='acknowledge'?'Referral accepted.':'Referral declined.');portalView='cases';renderPortal('ngo')}catch(error){toast(error.message)}});
document.addEventListener('submit',async e=>{const form=e.target;if(form.dataset.form==='ngo-case-status'){e.preventDefault();const id=form.dataset.referralId;try{await portalFetch(`/ngo/referrals/${encodeURIComponent(id)}/case-status`,'ngo',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({case_status:form.elements.case_status.value,note:form.elements.note.value||null})});toast('Case status saved.');openPortal('ngo',id)}catch(error){toast(error.message)}return}if(form.dataset.form==='ngo-support-status'){e.preventDefault();const id=form.dataset.referralId;try{await portalFetch(`/ngo/referrals/${encodeURIComponent(id)}/support-status`,'ngo',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({support_status:form.elements.support_status.value})});toast('Support update saved.');openPortal('ngo',id)}catch(error){toast(error.message)}}});
document.addEventListener('submit',async e=>{if(e.target.dataset.form!=='ngo-profile')return;e.preventDefault();e.stopImmediatePropagation();const form=e.target;try{await portalFetch('/ngo/profile','ngo',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({categories:form.querySelector('#profile-categories').value.split(',').map(x=>x.trim()).filter(Boolean),districts:form.querySelector('#profile-districts').value.split(',').map(x=>x.trim()).filter(Boolean),contact_phone:form.querySelector('#profile-phone').value,contact_email:form.querySelector('#profile-email').value||null,website:form.querySelector('#profile-website').value||null,description:form.querySelector('#profile-description').value})});toast('Organization profile saved.');renderPortal('ngo')}catch(error){toast(error.message)}},true);
document.addEventListener('submit',e=>{if(e.target.dataset.form!=='ngo-case-filters')return;e.preventDefault();const search=document.querySelector('#ngo-case-search').value.trim().toLowerCase();const status=document.querySelector('#ngo-filter-status').value;const severity=document.querySelector('#ngo-filter-severity').value;const category=document.querySelector('#ngo-filter-category').value;const rows=(portalData.referrals||[]).filter(item=>(!search||item.case_id.toLowerCase().includes(search))&&(!status||item.case_status===status)&&(!severity||item.severity===severity)&&(!category||item.case?.category===category));document.querySelector('#ngo-case-rows').innerHTML=ngoCaseRows(rows)});
document.addEventListener('click',e=>{const message=e.target.closest('[data-ngo-message-ref]');if(message)openPortal('ngo',message.dataset.ngoMessageRef)});
function kindFromPath(){return location.pathname.startsWith('/ngo')?'ngo':'admin'}
document.addEventListener('change',async e=>{const select=e.target.closest('[data-sos-assignment]');if(!select||!select.value)return;try{await portalFetch(`/admin/sos/${encodeURIComponent(select.dataset.sosAssignment)}/assign`,'admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ngo_id:Number(select.value)})});toast('SOS assigned to NGO.');loadSosPortal('admin')}catch(error){toast(error.message)}});
document.addEventListener('click',async e=>{const admin=e.target.closest('[data-admin-sos]');const ngo=e.target.closest('[data-ngo-sos]');if(!admin&&!ngo)return;try{const button=admin||ngo;const isPolice=button.dataset.sosPolice==='true';const path=admin?(isPolice?`/admin/sos/${button.dataset.sosId}/police-escalation`:`/admin/sos/${button.dataset.sosId}/status`):`/ngo/sos/${button.dataset.sosId}/status`;await portalFetch(path,admin?'admin':'ngo',{method:isPolice?'POST':'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(isPolice?{status:button.dataset.adminSos,note:'Updated from SOS command center'}:{status:button.dataset.adminSos||button.dataset.ngoSos,note:'Updated from SOS command center'})});toast('SOS status updated.');loadSosPortal(admin?'admin':'ngo')}catch(error){toast(error.message)}});
function renderPortalContent(){if(state.adminToken||state.ngoToken)renderPortal(kindFromPath())}
export function initialScreenForPath(pathname=window.location.pathname){
  const path=pathname.replace(/\/+$/, '')||'/';
  if(path==='/ngo')return 'ngoPortal';
  if(path.startsWith('/ngo/'))return 'ngoDashboardPortal';
  if(path.startsWith('/admin'))return 'adminDashboardPortal';
  if(path.startsWith('/donate'))return 'donate';
  if(path==='/crowdfunding')return 'crowdfunding';
  if(path.startsWith('/crowdfunding/'))return 'crowdfundingCampaign';
  return 'landing';
}
render(initialScreenForPath());
function dashboardWithHistory(){const timeline=state.timeline.map(e=>`<div class="event"><time>${esc(e.date)}</time><h3>${esc(e.summary)}</h3><p>${esc(e.type||'Evidence')}</p></div>`).join('');const history=(state.clarifyingQa||[]).map(item=>`<div class="clarification"><strong>Question</strong><p>${esc(item.question)}</p><strong>Your answer</strong><p>${esc(item.answer)}</p><small>${esc(item.answered_at?new Date(item.answered_at).toLocaleString():'')}</small></div>`).join('');return `${header(true)}<main class="page"><div class="status">${icon('verified_user')} Vault secured</div><div class="dashboard-grid" style="margin-top:24px"><section class="clay panel"><h2>Recent report</h2><div class="report-row"><div><strong>${esc(categories.find(c=>c[0]===state.category)?.[2]||'Incident report')}</strong><br><small>${esc(state.district)} · Anonymous report</small></div>${icon('description')}</div><p style="color:var(--muted)">${esc(state.report)}</p><button class="btn soft" data-action="status">${icon('check_circle')} Mark NGO contacted</button></section><section class="severity"><span>${icon('priority_high')} Safety signal</span><strong>${esc(state.severity)}</strong><p>If you are in immediate danger, call Nepal Police at 100 or Khabar Garaun at 1145.</p><button class="btn soft full" data-action="legal-guidance">View legal guidance</button></section><section class="clay panel"><h2>${icon('forum')} Clarification history</h2><div class="clarifications">${history||'<div class="empty">No clarification answers saved yet.</div>'}</div></section><section class="clay panel"><h2>${icon('timeline')} Evidence timeline</h2><div class="timeline">${timeline||'<div class="empty">No evidence timeline yet.</div>'}</div><button class="btn primary" data-action="evidence">Add evidence ${icon('add')}</button></section><section class="clay panel"><h2>${icon('handshake')} Best support match</h2>${state.matches.slice(0,1).map(o=>`<div class="report-row"><div><strong>${esc(o.name)}</strong><br><small>${esc(o.contact_phone)}</small></div>${icon('arrow_forward')}</div>`).join('')}<button class="btn soft full" data-action="matches">View match details</button></section></div></main>`}

// Workflow guards and visible registration feedback for the legacy delegated UI.
document.addEventListener('click', e=>{
  const action=e.target.closest('[data-action]')?.dataset.action;
  if(action==='summary'&&!intakeComplete()){
    e.preventDefault();e.stopImmediatePropagation();toast('Please answer all five questions before continuing');
  }
  if(action==='chat-history'){
    e.preventDefault();e.stopImmediatePropagation();restoreIntakeHistory();render('chat');
  }
},true);
document.addEventListener('submit',async e=>{
  if(e.target.dataset.form!=='ngo-register')return;
  e.preventDefault();e.stopImmediatePropagation();
  if(!e.target.reportValidity())return;
  const button=e.target.querySelector('button[type="submit"], button:not([type])');
  const resultTarget=document.querySelector('#ngo-registration-result');
  const values=id=>document.querySelector(id)?.value.trim()||'';
  button.disabled=true;resultTarget.innerHTML='';
  try{
    const result=await api('/ngo/registrations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:values('#reg-name'),categories:values('#reg-categories').split(',').map(x=>x.trim()).filter(Boolean),districts:values('#reg-districts').split(',').map(x=>x.trim()).filter(Boolean),contact_phone:values('#reg-phone'),contact_email:values('#reg-email')||null,website:values('#reg-website')||null,description:values('#reg-description')})});
    resultTarget.innerHTML=`<div class="warning"><strong>Registration submitted</strong><br><code>${esc(result.token)}</code><br><small>Save this access token. It becomes active once the administrator approves the organization.</small></div>`;
    e.target.reset();toast('Registration submitted for admin review');
  }catch(error){resultTarget.innerHTML=`<div class="warning">${esc(error.message)}</div>`;toast(error.message)}finally{button.disabled=false}
},true);
function refreshOrganizationQueue(){
  if(state.screen==='dashboard'&&state.caseId&&!document.querySelector('[data-action="chat-history"]')){
    const reportPanel=[...document.querySelectorAll('.dashboard-grid .panel')].find(panel=>panel.querySelector('h2')?.textContent==='Recent report');
    reportPanel?.insertAdjacentHTML('beforeend',`<button class="btn soft" data-action="chat-history">Continue AI conversation ${icon('forum')}</button>`);
  }
  return;
  document.querySelectorAll('#portal-content .queue-row').forEach((row,index)=>{
    const organization=portalData.ngos[index];if(!organization)return;
    const title=row.querySelector('strong');if(title)title.textContent=organization.name;
    const description=row.querySelector('p');if(description)description.textContent=`${organization.verification_status} · ${(organization.districts||[]).join(', ')}`;
    if(organization.verification_status==='pending'&&!row.querySelector('[data-admin-ngo]'))row.lastElementChild?.insertAdjacentHTML('beforeend',`<button class="btn primary" data-admin-ngo="approve" data-ngo-id="${esc(organization.id)}">Approve</button><button class="btn soft" data-admin-ngo="reject" data-ngo-id="${esc(organization.id)}">Reject</button>`);
  });
}
new MutationObserver(refreshOrganizationQueue).observe(document.body,{childList:true,subtree:true});
// Resilient dashboard view: the vault remains usable while optional AI work retries.
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action="retry-analysis"]');if(!button||retryInFlight)return;retryInFlight=true;render('dashboard');try{const data=await api(`/cases/${state.caseId}/analyze`,{method:'POST'});Object.assign(state,{analysisStatus:data.analysis_status||'failed',aiLegalSummary:data.ai_legal_summary,severity:data.severity});}catch(error){toast(error.message)}finally{retryInFlight=false;render('dashboard')}});
function resilientDashboardWithHistory(){const notice=state.analysisStatus==='unavailable'?`<div class="warning">${icon('info')}<span>Legal analysis is temporarily unavailable, but your case and evidence are saved. Try again in a moment. <button class="btn soft" data-action="retry-analysis" ${retryInFlight?'disabled':''}>${retryInFlight?'Trying again…':'Try again'}</button></span></div>`:'';return `${header(true)}<main class="page">${notice}<div class="dashboard-grid"><section class="clay panel"><h2>Recent report</h2><p>${esc(state.report)}</p></section><section class="severity"><span>${icon('priority_high')} Safety signal</span><strong>${esc(state.severity||'Pending')}</strong></section><section class="clay panel"><h2>${icon('timeline')} Evidence timeline</h2><div class="timeline">${state.timeline.map(e=>`<div class="event"><time>${esc(e.date)}</time><h3>${esc(e.summary)}</h3></div>`).join('')||'<div class="empty">No evidence timeline yet.</div>'}<button class="btn primary" data-action="evidence">Add evidence</button></div></section><section class="clay panel"><h2>${icon('handshake')} Support matches</h2><button class="btn soft full" data-action="matches">View all matches</button><button class="btn soft full" data-action="referrals">View referral status</button></section><section class="clay panel"><h2>${icon('forum')} Messages</h2><div data-chat-case="${esc(state.caseId)}" data-chat-kind="survivor"><div class="loading">Loading messages...</div></div></section></div></main>`}
function donate(){return `${header()}<main class="page narrow"><div class="eyebrow">Support VaultVoice</div><h1 class="headline">Fund private access to support</h1><p class="subhead">Your donation supports platform operations. Payment details are handled by the payment provider and are never stored here.</p><form class="clay panel" data-form="donate"><div class="choice-grid"><button type="button" class="choice" data-donation-amount="500">NPR 500</button><button type="button" class="choice" data-donation-amount="1000">NPR 1,000</button><button type="button" class="choice" data-donation-amount="2500">NPR 2,500</button></div><label class="field-label">Amount</label><input id="donation-amount" class="input" type="number" min="1" step="0.01" value="500" required><label class="field-label">Name (optional)</label><input id="donation-name" class="input"><label class="field-label">Email for receipt (optional)</label><input id="donation-email" class="input" type="email"><label class="checkbox"><input id="donation-anonymous" type="checkbox" checked> Give anonymously</label><label class="field-label">Message (optional)</label><textarea id="donation-message" class="textarea"></textarea><button class="btn primary full">Continue to payment</button></form></main>`}
document.addEventListener('click',e=>{const amount=e.target.closest('[data-donation-amount]');if(amount){const input=document.querySelector('#donation-amount');if(input)input.value=amount.dataset.donationAmount}if(e.target.closest('[data-action="donate"]'))render('donate')});
document.addEventListener('submit',async e=>{if(e.target.dataset.form!=='donate')return;e.preventDefault();try{const item=await api('/donations/platform',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:Number(document.querySelector('#donation-amount').value),donor_name:document.querySelector('#donation-name').value||null,donor_email:document.querySelector('#donation-email').value||null,is_anonymous:document.querySelector('#donation-anonymous').checked,message:document.querySelector('#donation-message').value||null})});e.target.innerHTML=`<div class="center">${icon('check_circle')}<h2>Thank you for supporting private access.</h2><p>Your donation intent ${esc(item.id)} is ready for payment-provider confirmation.</p></div>`}catch(error){toast(error.message)}});
function crowdfunding(){setTimeout(async()=>{try{const items=await api('/crowdfunding');const target=document.querySelector('#campaigns');if(target)target.innerHTML=items.map(item=>`<article class="clay panel"><span class="status">${esc(item.category)}</span><h2>${esc(item.display_name)}</h2><p>${esc(item.description)}</p><p>NPR ${esc(item.amount_raised)} raised of NPR ${esc(item.requested_amount)}</p><a class="btn soft" href="/crowdfunding/${esc(item.id)}">View campaign</a></article>`).join('')||'<div class="empty">No active campaigns.</div>'}catch(error){toast(error.message)}},0);return `${header()}<main class="page"><div class="eyebrow">Community support</div><h1 class="headline">Active crowdfunding campaigns</h1><p class="subhead">Campaigns are reviewed before publication and use anonymized case identities by default.</p><div id="campaigns" class="matches"></div></main>`}
function crowdfundingCampaign(){const id=location.pathname.split('/').filter(Boolean).pop();setTimeout(async()=>{try{const item=await api(`/crowdfunding/${encodeURIComponent(id)}`);const target=document.querySelector('#campaign');if(target)target.innerHTML=`<span class="status">${esc(item.category)}</span><h1 class="headline">${esc(item.display_name)}</h1><p>${esc(item.description)}</p><p>NPR ${esc(item.amount_raised)} raised of NPR ${esc(item.requested_amount)} (${esc(item.progress_percent)}%)</p><form data-form="campaign-donate"><input type="hidden" id="campaign-id" value="${esc(item.id)}"><input id="campaign-amount" class="input" type="number" min="1" placeholder="Amount in NPR" required><label class="checkbox"><input id="campaign-anonymous" type="checkbox" checked> Give anonymously</label><button class="btn primary">Donate</button></form>`}catch(error){toast(error.message)}},0);return `${header()}<main class="page narrow"><section id="campaign" class="clay panel"><p>Loading campaign...</p></section></main>`}
document.addEventListener('submit',async e=>{if(e.target.dataset.form!=='campaign-donate')return;e.preventDefault();try{await api(`/crowdfunding/${document.querySelector('#campaign-id').value}/donations`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:Number(document.querySelector('#campaign-amount').value),is_anonymous:document.querySelector('#campaign-anonymous').checked})});e.target.innerHTML='<p>Thank you. Your donation intent is ready for provider confirmation.</p>'}catch(error){toast(error.message)}});
export {DEFAULT_STATE, state, clearSessionState, handleQuickExit, header, isNgoRoute};
